import 'dotenv/config';
import express from 'express'; import helmet from 'helmet'; import cors from 'cors'; import rateLimit from 'express-rate-limit';
import multer from 'multer'; import pg from 'pg'; import bcrypt from 'bcryptjs'; import jwt from 'jsonwebtoken';
import crypto from 'node:crypto'; import path from 'node:path'; import {fileURLToPath} from 'node:url'; import {pipeline} from 'node:stream/promises'; import {z} from 'zod';
import {createPrivateObjectStorage} from './private-object-storage.js';
import {cert,getApps,initializeApp} from 'firebase-admin/app';
import {getAuth} from 'firebase-admin/auth';
if(process.env.NODE_ENV!=='test' && (!process.env.JWT_SECRET || process.env.JWT_SECRET.length<32)) throw new Error('JWT_SECRET must be configured with at least 32 characters');
const app=express(), {Pool}=pg, here=path.dirname(fileURLToPath(import.meta.url));
app.set('trust proxy', 1);
const databaseUrl=process.env.DATABASE_URL?new URL(process.env.DATABASE_URL):null; if(databaseUrl)for(const key of ['sslmode','sslrootcert','sslcert','sslkey'])databaseUrl.searchParams.delete(key); const pool=databaseUrl?new Pool({connectionString:databaseUrl.toString(),ssl:process.env.PGSSL==='true'?{ca:process.env.SUPABASE_CA_CERT||undefined,rejectUnauthorized:true}:undefined,connectionTimeoutMillis:10000,idleTimeoutMillis:30000,keepAlive:true,max:10}):null;
const storage=path.resolve(process.env.PRIVATE_STORAGE_DIR||path.join(here,'../storage/private')); const objectStorage=createPrivateObjectStorage({storageDir:storage}); const max=Number(process.env.MAX_UPLOAD_BYTES||52428800);
app.disable('x-powered-by'); app.use(helmet({crossOriginResourcePolicy:{policy:'same-site'}}));
const allowedOrigins = new Set([
  'https://kararboazar313.github.io',
  ...(process.env.CORS_ORIGIN || '').split(',').map(x => x.trim()).filter(Boolean)
]);
app.use(cors({
  origin: (origin, callback) => callback(null, !origin || allowedOrigins.has(origin)),
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  optionsSuccessStatus: 204
}));
app.use(express.json({limit:'1mb'}));
app.use('/api',rateLimit({windowMs:60000,limit:100,standardHeaders:true,legacyHeaders:false}));
const loginRateLimit=rateLimit({windowMs:15*60*1000,limit:10,standardHeaders:true,legacyHeaders:false,message:{error:'too_many_auth_attempts'}});
const registerRateLimit=rateLimit({windowMs:60*60*1000,limit:5,standardHeaders:true,legacyHeaders:false,message:{error:'registration_rate_limited'}});
const ready=()=>{if(!pool)throw Object.assign(new Error('Database is not configured'),{status:503});};
const auth=(req,res,next)=>{try{const h=req.headers.authorization||'';const t=h.startsWith('Bearer ')?h.slice(7):'';const claims=jwt.verify(t,process.env.JWT_SECRET);if(!pool){req.user=claims;return next()}pool.query('SELECT account_type,status FROM qayyum.users WHERE id=$1',[claims.sub]).then(q=>{if(!q.rowCount||q.rows[0].status!=='active')return res.status(401).json({error:'account_inactive_or_unavailable'});req.user={...claims,account_type:q.rows[0].account_type};next()}).catch(next)}catch{return res.status(401).json({error:'authentication_required'})}};
const admin=(req,res,next)=>{if(!['owner','admin'].includes(req.user.account_type))return res.status(403).json({error:'admin_required'});next()};
const ownerOnly=(req,res,next)=>{if(req.user.account_type!=='owner')return res.status(403).json({error:'owner_required'});next()};

// Owner-controlled membership, role and department administration.
app.get('/api/admin/members',auth,ownerOnly,safe(async(req,res)=>{ready();const v=z.object({q:z.string().max(120).optional(),status:z.enum(['active','suspended','banned','pending_deletion']).optional(),limit:z.coerce.number().int().min(1).max(100).default(50)}).parse(req.query);const q=await pool.query(`SELECT u.id,u.public_id,u.account_type,u.status,u.created_at,p.display_name,p.username,COALESCE(array_agg(DISTINCT r.code) FILTER(WHERE r.code IS NOT NULL),'{}') AS roles FROM qayyum.users u LEFT JOIN qayyum.user_profiles p ON p.user_id=u.id LEFT JOIN qayyum.user_roles ur ON ur.user_id=u.id LEFT JOIN qayyum.roles r ON r.id=ur.role_id WHERE ($1::text IS NULL OR u.status=$1) AND ($2::text IS NULL OR COALESCE(p.display_name,'') ILIKE '%'||$2||'%' OR COALESCE(p.username,'') ILIKE '%'||$2||'%' OR COALESCE(u.public_id,'') ILIKE '%'||$2||'%') GROUP BY u.id,p.display_name,p.username ORDER BY u.created_at DESC LIMIT $3`,[v.status||null,v.q||null,v.limit]);res.json({items:q.rows})}));
app.patch('/api/admin/members/:id/status',auth,ownerOnly,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({status:z.enum(['active','suspended','banned','pending_deletion']),note:z.string().min(3).max(1000)}).parse(req.body);if(id===req.user.sub&&v.status!=='active')return res.status(400).json({error:'cannot_suspend_current_owner'});const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query("UPDATE qayyum.users SET status=$2,updated_at=now() WHERE id=$1 AND account_type<>'owner' RETURNING id,status",[id,v.status]);if(!q.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'member_not_found_or_protected'})}await c.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'member_status_changed','user',$2,$3)",[req.user.sub,id,JSON.stringify({status:v.status,note:v.note})]);await c.query('COMMIT');res.json(q.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.get('/api/admin/roles',auth,ownerOnly,safe(async(_req,res)=>{ready();const q=await pool.query('SELECT id,code,name,description FROM qayyum.roles ORDER BY name');res.json({items:q.rows})}));
app.put('/api/admin/members/:id/roles',auth,ownerOnly,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({roles:z.array(z.string().min(2).max(64)).max(20),note:z.string().min(3).max(1000)}).parse(req.body);if(v.roles.some(x=>['owner','admin'].includes(x)))return res.status(400).json({error:'privileged_account_types_cannot_be_granted_as_roles'});const c=await pool.connect();try{await c.query('BEGIN');const u=await c.query("SELECT id FROM qayyum.users WHERE id=$1 AND account_type='member' AND status='active' FOR UPDATE",[id]);if(!u.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'active_member_not_found'})}const rs=await c.query('SELECT id,code FROM qayyum.roles WHERE code=ANY($1::text[])',[v.roles]);if(rs.rowCount!==new Set(v.roles).size){await c.query('ROLLBACK');return res.status(400).json({error:'unknown_role_code'})}await c.query('DELETE FROM qayyum.user_roles WHERE user_id=$1',[id]);for(const r of rs.rows)await c.query('INSERT INTO qayyum.user_roles(user_id,role_id,granted_by) VALUES($1,$2,$3)',[id,r.id,req.user.sub]);await c.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'member_roles_replaced','user',$2,$3)",[req.user.sub,id,JSON.stringify({roles:v.roles,note:v.note})]);await c.query('COMMIT');res.json({userId:id,roles:rs.rows.map(x=>x.code)})}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.get('/api/admin/departments',auth,ownerOnly,safe(async(_req,res)=>{ready();const q=await pool.query(`SELECT d.id,d.parent_id,d.name,d.description,d.status,COUNT(a.user_id)::int AS assigned_count,COALESCE(json_agg(json_build_object('user_id',a.user_id,'display_name',p.display_name,'role',a.assignment_role)) FILTER(WHERE a.user_id IS NOT NULL),'[]'::json) AS assignments FROM qayyum.departments d LEFT JOIN qayyum.department_assignments a ON a.department_id=d.id LEFT JOIN qayyum.user_profiles p ON p.user_id=a.user_id GROUP BY d.id ORDER BY d.name`);res.json({items:q.rows})}));
app.post('/api/admin/departments',auth,ownerOnly,safe(async(req,res)=>{ready();const v=z.object({name:z.string().min(2).max(200),description:z.string().max(2000).optional(),parentId:z.coerce.number().int().positive().optional()}).parse(req.body);const q=await pool.query('INSERT INTO qayyum.departments(name,description,parent_id) VALUES($1,$2,$3) RETURNING id,name,description,parent_id,status',[v.name,v.description||null,v.parentId||null]);await pool.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'department_created','department',$2,$3)",[req.user.sub,String(q.rows[0].id),JSON.stringify({name:v.name})]);res.status(201).json(q.rows[0])}));
app.patch('/api/admin/departments/:id/status',auth,ownerOnly,safe(async(req,res)=>{ready();const id=z.coerce.number().int().positive().parse(req.params.id);const v=z.object({status:z.enum(['active','paused','archived'])}).parse(req.body);const q=await pool.query('UPDATE qayyum.departments SET status=$2 WHERE id=$1 RETURNING id,status',[id,v.status]);if(!q.rowCount)return res.status(404).json({error:'department_not_found'});await pool.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'department_status_changed','department',$2,$3)",[req.user.sub,String(id),JSON.stringify({status:v.status})]);res.json(q.rows[0])}));
app.post('/api/admin/departments/:id/assignments',auth,ownerOnly,safe(async(req,res)=>{ready();const id=z.coerce.number().int().positive().parse(req.params.id);const v=z.object({userId:z.string().uuid(),role:z.enum(['manager','deputy','staff','reviewer'])}).parse(req.body);const c=await pool.connect();try{await c.query('BEGIN');const d=await c.query("SELECT id FROM qayyum.departments WHERE id=$1 AND status='active' FOR UPDATE",[id]);const u=await c.query("SELECT id FROM qayyum.users WHERE id=$1 AND account_type='member' AND status='active'",[v.userId]);if(!d.rowCount||!u.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'active_department_or_member_not_found'})}await c.query('INSERT INTO qayyum.department_assignments(department_id,user_id,assignment_role,granted_by) VALUES($1,$2,$3,$4) ON CONFLICT(department_id,user_id,assignment_role) DO NOTHING',[id,v.userId,v.role,req.user.sub]);await c.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'department_assignment_granted','department',$2,$3)",[req.user.sub,String(id),JSON.stringify({userId:v.userId,role:v.role})]);await c.query('COMMIT');res.status(201).json({departmentId:id,userId:v.userId,role:v.role})}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.delete('/api/admin/departments/:id/assignments/:userId/:role',auth,ownerOnly,safe(async(req,res)=>{ready();const id=z.coerce.number().int().positive().parse(req.params.id);const userId=z.string().uuid().parse(req.params.userId);const role=z.enum(['manager','deputy','staff','reviewer']).parse(req.params.role);const q=await pool.query('DELETE FROM qayyum.department_assignments WHERE department_id=$1 AND user_id=$2 AND assignment_role=$3 RETURNING department_id',[id,userId,role]);if(!q.rowCount)return res.status(404).json({error:'assignment_not_found'});await pool.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'department_assignment_revoked','department',$2,$3)",[req.user.sub,String(id),JSON.stringify({userId,role})]);res.status(204).end()}));

// Administrative workspace: projects, assigned tasks, text-only meetings, and reports.
app.get('/api/admin/workspace/summary',auth,admin,safe(async(req,res)=>{ready();const owner=req.user.account_type==='owner';const p=await pool.query(`SELECT COUNT(*)::int AS total,COUNT(*) FILTER(WHERE status='active')::int AS active FROM qayyum.admin_projects WHERE ($1::boolean OR created_by=$2 OR id IN (SELECT project_id FROM qayyum.admin_tasks WHERE assigned_to=$2))`,[owner,req.user.sub]);const t=await pool.query(`SELECT status,COUNT(*)::int AS count FROM qayyum.admin_tasks WHERE ($1::boolean OR assigned_to=$2 OR created_by=$2) GROUP BY status`,[owner,req.user.sub]);const m=await pool.query(`SELECT COUNT(*)::int AS upcoming FROM qayyum.admin_meetings m WHERE m.starts_at>=now() AND m.status='scheduled' AND ($1::boolean OR m.created_by=$2 OR EXISTS(SELECT 1 FROM qayyum.admin_meeting_participants x WHERE x.meeting_id=m.id AND x.user_id=$2))`,[owner,req.user.sub]);res.json({projects:p.rows[0],tasks:t.rows,upcomingMeetings:m.rows[0].upcoming})}));
app.get('/api/admin/workspace/projects',auth,admin,safe(async(req,res)=>{ready();const owner=req.user.account_type==='owner';const q=await pool.query(`SELECT p.id,p.title,p.description,p.status,p.due_at,p.created_at,p.created_by,COUNT(t.id)::int AS task_count,COUNT(t.id) FILTER(WHERE t.status='done')::int AS done_count FROM qayyum.admin_projects p LEFT JOIN qayyum.admin_tasks t ON t.project_id=p.id WHERE ($1::boolean OR p.created_by=$2 OR EXISTS(SELECT 1 FROM qayyum.admin_tasks x WHERE x.project_id=p.id AND x.assigned_to=$2)) GROUP BY p.id ORDER BY p.updated_at DESC LIMIT 200`,[owner,req.user.sub]);res.json({items:q.rows})}));
app.post('/api/admin/workspace/projects',auth,admin,safe(async(req,res)=>{ready();const v=z.object({title:z.string().min(3).max(300),description:z.string().max(10000).optional(),departmentId:z.number().int().positive().nullable().optional(),dueAt:z.string().datetime({offset:true}).nullable().optional()}).parse(req.body);if(v.departmentId){const d=await pool.query("SELECT id FROM qayyum.departments WHERE id=$1 AND status='active'",[v.departmentId]);if(!d.rowCount)return res.status(400).json({error:'active_department_not_found'})}const q=await pool.query('INSERT INTO qayyum.admin_projects(title,description,department_id,created_by,due_at) VALUES($1,$2,$3,$4,$5) RETURNING *',[v.title,v.description||null,v.departmentId||null,req.user.sub,v.dueAt||null]);await pool.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'admin_project_created','admin_project',$2,$3)",[req.user.sub,q.rows[0].id,JSON.stringify({title:v.title})]);res.status(201).json(q.rows[0])}));
app.get('/api/admin/workspace/projects/:id/tasks',auth,admin,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const own=req.user.account_type==='owner';const access=await pool.query(`SELECT 1 FROM qayyum.admin_projects p WHERE p.id=$1 AND ($2::boolean OR p.created_by=$3 OR EXISTS(SELECT 1 FROM qayyum.admin_tasks x WHERE x.project_id=p.id AND x.assigned_to=$3))`,[id,own,req.user.sub]);if(!access.rowCount)return res.status(404).json({error:'project_not_found'});const q=await pool.query('SELECT t.*,p.display_name AS assignee_name FROM qayyum.admin_tasks t LEFT JOIN qayyum.user_profiles p ON p.user_id=t.assigned_to WHERE t.project_id=$1 ORDER BY t.created_at DESC',[id]);res.json({items:q.rows})}));
app.post('/api/admin/workspace/projects/:id/tasks',auth,admin,safe(async(req,res)=>{ready();const projectId=z.string().uuid().parse(req.params.id);const v=z.object({title:z.string().min(3).max(300),description:z.string().max(10000).optional(),priority:z.enum(['low','normal','high','urgent']).default('normal'),assignedTo:z.string().uuid().nullable().optional(),dueAt:z.string().datetime({offset:true}).nullable().optional()}).parse(req.body);const c=await pool.connect();try{await c.query('BEGIN');const p=await c.query('SELECT id,created_by FROM qayyum.admin_projects WHERE id=$1 FOR UPDATE',[projectId]);if(!p.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'project_not_found'})}if(req.user.account_type!=='owner'&&p.rows[0].created_by!==req.user.sub){await c.query('ROLLBACK');return res.status(403).json({error:'project_manager_required'})}const assignee=v.assignedTo||req.user.sub;const u=await c.query("SELECT id,account_type FROM qayyum.users WHERE id=$1 AND status='active'",[assignee]);if(!u.rowCount||!(u.rows[0].account_type==='admin'||(assignee===req.user.sub&&['admin','owner'].includes(req.user.account_type)))){await c.query('ROLLBACK');return res.status(400).json({error:'assignee_must_be_active_admin'})}const q=await c.query('INSERT INTO qayyum.admin_tasks(project_id,title,description,priority,assigned_to,created_by,due_at) VALUES($1,$2,$3,$4,$5,$6,$7) RETURNING *',[projectId,v.title,v.description||null,v.priority,assignee,req.user.sub,v.dueAt||null]);await c.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'admin_task_created','admin_task',$2,$3)",[req.user.sub,q.rows[0].id,JSON.stringify({projectId,assignedTo:assignee})]);await c.query('COMMIT');res.status(201).json(q.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.patch('/api/admin/workspace/tasks/:id',auth,admin,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({status:z.enum(['todo','in_progress','blocked','review','done','cancelled'])}).parse(req.body);const q=await pool.query(`UPDATE qayyum.admin_tasks SET status=$2,completed_at=CASE WHEN $2='done' THEN now() ELSE NULL END,updated_at=now() WHERE id=$1 AND ($3::boolean OR assigned_to=$4 OR created_by=$4) RETURNING id,status,completed_at`,[id,v.status,req.user.account_type==='owner',req.user.sub]);if(!q.rowCount)return res.status(404).json({error:'task_not_found_or_forbidden'});await pool.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'admin_task_status_changed','admin_task',$2,$3)",[req.user.sub,id,JSON.stringify({status:v.status})]);res.json(q.rows[0])}));
app.get('/api/admin/workspace/meetings',auth,admin,safe(async(req,res)=>{ready();const q=await pool.query(`SELECT m.*,p.display_name AS organizer FROM qayyum.admin_meetings m LEFT JOIN qayyum.user_profiles p ON p.user_id=m.created_by WHERE ($1::boolean OR m.created_by=$2 OR EXISTS(SELECT 1 FROM qayyum.admin_meeting_participants x WHERE x.meeting_id=m.id AND x.user_id=$2)) ORDER BY m.starts_at DESC LIMIT 100`,[req.user.account_type==='owner',req.user.sub]);res.json({items:q.rows})}));
app.post('/api/admin/workspace/meetings',auth,ownerOnly,safe(async(req,res)=>{ready();const v=z.object({title:z.string().min(3).max(300),agenda:z.string().max(10000).optional(),startsAt:z.string().datetime({offset:true}),participantIds:z.array(z.string().uuid()).max(100).default([])}).parse(req.body);const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query("INSERT INTO qayyum.admin_meetings(title,agenda,starts_at,created_by) VALUES($1,$2,$3,$4) RETURNING *",[v.title,v.agenda||null,v.startsAt,req.user.sub]);for(const uid of new Set(v.participantIds)){const u=await c.query("SELECT id FROM qayyum.users WHERE id=$1 AND account_type='admin' AND status='active'",[uid]);if(!u.rowCount)continue;await c.query('INSERT INTO qayyum.admin_meeting_participants(meeting_id,user_id,invited_by) VALUES($1,$2,$3) ON CONFLICT DO NOTHING',[q.rows[0].id,uid,req.user.sub])}await c.query('INSERT INTO qayyum.admin_meeting_participants(meeting_id,user_id,invited_by) VALUES($1,$2,$2) ON CONFLICT DO NOTHING',[q.rows[0].id,req.user.sub]);await c.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'admin_meeting_created','admin_meeting',$2,$3)",[req.user.sub,q.rows[0].id,JSON.stringify({title:v.title,participants:v.participantIds.length})]);await c.query('COMMIT');res.status(201).json(q.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.get('/api/admin/workspace/meetings/:id/messages',auth,admin,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const access=await pool.query(`SELECT 1 FROM qayyum.admin_meetings m WHERE m.id=$1 AND ($2::boolean OR m.created_by=$3 OR EXISTS(SELECT 1 FROM qayyum.admin_meeting_participants x WHERE x.meeting_id=m.id AND x.user_id=$3))`,[id,req.user.account_type==='owner',req.user.sub]);if(!access.rowCount)return res.status(404).json({error:'meeting_not_found'});const q=await pool.query("SELECT x.id,x.body,x.created_at,COALESCE(p.display_name,'عضو إداري') AS sender FROM qayyum.admin_meeting_messages x LEFT JOIN qayyum.user_profiles p ON p.user_id=x.sender_id WHERE x.meeting_id=$1 ORDER BY x.created_at LIMIT 500",[id]);res.json({items:q.rows})}));
app.post('/api/admin/workspace/meetings/:id/messages',auth,admin,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({body:z.string().trim().min(1).max(10000)}).parse(req.body);const access=await pool.query(`SELECT 1 FROM qayyum.admin_meetings m WHERE m.id=$1 AND ($2::boolean OR m.created_by=$3 OR EXISTS(SELECT 1 FROM qayyum.admin_meeting_participants x WHERE x.meeting_id=m.id AND x.user_id=$3))`,[id,req.user.account_type==='owner',req.user.sub]);if(!access.rowCount)return res.status(404).json({error:'meeting_not_found'});const q=await pool.query('INSERT INTO qayyum.admin_meeting_messages(meeting_id,sender_id,body) VALUES($1,$2,$3) RETURNING id,body,created_at',[id,req.user.sub,v.body]);res.status(201).json(q.rows[0])}));
app.get('/api/admin/workspace/reports',auth,admin,safe(async(req,res)=>{ready();const owner=req.user.account_type==='owner';const q=await pool.query(`SELECT id,report_kind,period_start,period_end,snapshot,created_at FROM qayyum.admin_reports WHERE ($1::boolean OR generated_by=$2) ORDER BY created_at DESC LIMIT 50`,[owner,req.user.sub]);res.json({items:q.rows})}));
app.post('/api/admin/workspace/reports',auth,admin,safe(async(req,res)=>{ready();const v=z.object({kind:z.enum(['daily','weekly','monthly','annual','custom']),start:z.string().date(),end:z.string().date()}).parse(req.body);if(v.end<v.start)return res.status(400).json({error:'invalid_report_period'});const owner=req.user.account_type==='owner';const tasks=await pool.query(`SELECT status,priority,COUNT(*)::int AS count FROM qayyum.admin_tasks WHERE created_at >= $1::date AND created_at < ($2::date + interval '1 day') AND ($3::boolean OR assigned_to=$4 OR created_by=$4) GROUP BY status,priority ORDER BY status,priority`,[v.start,v.end,owner,req.user.sub]);const projects=await pool.query(`SELECT status,COUNT(*)::int AS count FROM qayyum.admin_projects WHERE created_at >= $1::date AND created_at < ($2::date + interval '1 day') AND ($3::boolean OR created_by=$4 OR id IN(SELECT project_id FROM qayyum.admin_tasks WHERE assigned_to=$4)) GROUP BY status`,[v.start,v.end,owner,req.user.sub]);const snapshot={tasks:tasks.rows,projects:projects.rows,generatedAt:new Date().toISOString()};const q=await pool.query('INSERT INTO qayyum.admin_reports(report_kind,period_start,period_end,generated_by,snapshot) VALUES($1,$2,$3,$4,$5::jsonb) RETURNING id,report_kind,period_start,period_end,snapshot,created_at',[v.kind,v.start,v.end,req.user.sub,JSON.stringify(snapshot)]);res.status(201).json(q.rows[0])}));

function safe(fn){return (req,res,next)=>Promise.resolve(fn(req,res,next)).catch(next);}
const registerSchema=z.object({email:z.string().email().max(320),password:z.string().min(12).max(72).refine(value=>Buffer.byteLength(value,'utf8')<=72,{message:'password_too_long_in_bytes'}),displayName:z.string().min(2).max(160),acceptedTerms:z.literal(true),termsVersion:z.string().min(1).max(40)});
const durableStorage=['s3','rapidfile'].includes(objectStorage.mode)||process.env.PRIVATE_STORAGE_PERSISTENT==='true';
app.get('/api/health',safe(async(_q,r)=>r.json({status:'ok',databaseConfigured:!!pool,privateStorageConfigured:['s3','rapidfile'].includes(objectStorage.mode)||!!process.env.PRIVATE_STORAGE_DIR,privateStorageDurable:durableStorage,privateStorageMode:objectStorage.mode})));
app.get('/api/ready',safe(async(_q,r)=>{if(!pool){console.error('[READINESS]',JSON.stringify({reason:'database_not_configured'}));return r.status(503).json({status:'not_ready',reason:'database_not_configured'});}try{await pool.query('SELECT 1')}catch(e){console.error('[READINESS_DB_ERROR]',JSON.stringify({name:e.name||'Error',code:e.code||null,message:e.message||'unknown'}));return r.status(503).json({status:'not_ready',reason:'database_unreachable'});}if(!durableStorage){console.error('[READINESS]',JSON.stringify({reason:'durable_private_storage_not_configured',storageMode:objectStorage.mode}));return r.status(503).json({status:'not_ready',reason:'durable_private_storage_not_configured'});}r.json({status:'ready',database:true,privateStorageDurable:true})}));
app.post('/api/auth/register',registerRateLimit,safe(async(req,res)=>{ready();const v=registerSchema.parse(req.body);const hash=await bcrypt.hash(v.password,12);const c=await pool.connect();try{await c.query('BEGIN');const u=await c.query("INSERT INTO qayyum.users(account_type) VALUES('member') RETURNING id,account_type");await c.query("INSERT INTO qayyum.auth_identities(user_id,provider,provider_subject,credential_hash) VALUES($1,'email',$2,$3)",[u.rows[0].id,v.email.toLowerCase(),hash]);await c.query('INSERT INTO qayyum.user_profiles(user_id,display_name) VALUES($1,$2)',[u.rows[0].id,v.displayName]);await c.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'terms_accepted','user',$1,$2)",[u.rows[0].id,JSON.stringify({termsVersion:v.termsVersion,accepted:true})]);await c.query('COMMIT');res.status(201).json({token:jwt.sign({sub:u.rows[0].id,account_type:'member'},process.env.JWT_SECRET,{expiresIn:'2h'}),expiresIn:7200})}catch(e){await c.query('ROLLBACK');if(e.code==='23505')return res.status(409).json({error:'account_exists'});throw e}finally{c.release()}}));
app.post('/api/auth/google',loginRateLimit,safe(async(req,res)=>{ready();const v=z.object({idToken:z.string().min(100).max(10000)}).parse(req.body);const raw=process.env.FIREBASE_SERVICE_ACCOUNT_JSON;if(!raw)return res.status(503).json({error:'google_sign_in_not_configured'});let claims;try{const serviceAccount=JSON.parse(raw);const firebaseApp=getApps()[0]||initializeApp({credential:cert(serviceAccount)});claims=await getAuth(firebaseApp).verifyIdToken(v.idToken,true)}catch(e){if(e instanceof SyntaxError)return res.status(503).json({error:'firebase_service_account_invalid'});return res.status(401).json({error:'invalid_google_token'})}if(claims.email_verified!==true||!claims.email||!claims.uid)return res.status(401).json({error:'google_email_not_verified'});const email=String(claims.email).toLowerCase();const c=await pool.connect();try{await c.query('BEGIN');let q=await c.query("SELECT u.id,u.account_type,u.status FROM qayyum.auth_identities i JOIN qayyum.users u ON u.id=i.user_id WHERE i.provider='google' AND i.provider_subject=$1 FOR UPDATE",[claims.uid]);let user=q.rows[0];if(!user){q=await c.query("SELECT u.id,u.account_type,u.status FROM qayyum.auth_identities i JOIN qayyum.users u ON u.id=i.user_id WHERE i.provider='email' AND lower(i.provider_subject)=$1 FOR UPDATE",[email]);user=q.rows[0];if(user){await c.query("INSERT INTO qayyum.auth_identities(user_id,provider,provider_subject,verified_at) VALUES($1,'google',$2,now())",[user.id,claims.uid])}else{q=await c.query("INSERT INTO qayyum.users(account_type) VALUES('member') RETURNING id,account_type,status");user=q.rows[0];await c.query("INSERT INTO qayyum.auth_identities(user_id,provider,provider_subject,verified_at) VALUES($1,'google',$2,now())",[user.id,claims.uid]);await c.query('INSERT INTO qayyum.user_profiles(user_id,display_name) VALUES($1,$2)',[user.id,String(claims.name||email.split('@')[0]).slice(0,160)])}}if(user.status!=='active'){await c.query('ROLLBACK');return res.status(403).json({error:'account_inactive_or_unavailable'})}await c.query('COMMIT');res.json({token:jwt.sign({sub:user.id,account_type:user.account_type},process.env.JWT_SECRET,{expiresIn:'30d'}),expiresIn:2592000})}catch(e){await c.query('ROLLBACK');if(e.code==='23505')return res.status(409).json({error:'google_account_link_conflict'});throw e}finally{c.release()}}));
app.post('/api/auth/login',loginRateLimit,safe(async(req,res)=>{ready();const v=z.object({email:z.string().email(),password:z.string().min(1),rememberMe:z.boolean().optional().default(false)}).parse(req.body);const q=await pool.query("SELECT u.id,u.account_type,i.credential_hash FROM qayyum.auth_identities i JOIN qayyum.users u ON u.id=i.user_id WHERE i.provider='email' AND i.provider_subject=$1 AND u.status='active'",[v.email.toLowerCase()]);if(!q.rowCount||!await bcrypt.compare(v.password,q.rows[0].credential_hash))return res.status(401).json({error:'invalid_credentials'});const u=q.rows[0];const expiresIn=v.rememberMe?'30d':'2h';res.json({token:jwt.sign({sub:u.id,account_type:u.account_type},process.env.JWT_SECRET,{expiresIn}),expiresIn:v.rememberMe?2592000:7200})}));
app.get('/api/auth/me',auth,safe(async(req,res)=>{ready();const q=await pool.query('SELECT u.id,u.public_id,u.account_type,u.status,p.display_name,p.username FROM qayyum.users u LEFT JOIN qayyum.user_profiles p ON p.user_id=u.id WHERE u.id=$1',[req.user.sub]);if(!q.rowCount||q.rows[0].status!=='active')return res.status(401).json({error:'account_inactive_or_unavailable'});const u=q.rows[0];res.json({id:u.id,publicId:u.public_id,displayName:u.display_name,username:u.username,accountType:u.account_type,isOwner:u.account_type==='owner',isAdmin:['owner','admin'].includes(u.account_type)})}));
app.patch('/api/admin/members/:id/access',auth,ownerOnly,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({accountType:z.enum(['member','admin']),note:z.string().min(3).max(1000)}).parse(req.body);if(id===req.user.sub)return res.status(400).json({error:'cannot_change_owner_access'});const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query("UPDATE qayyum.users SET account_type=$2,status='active',updated_at=now() WHERE id=$1 AND account_type<>'owner' RETURNING id,account_type,status",[id,v.accountType]);if(!q.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'member_not_found_or_protected'})}await c.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,$2,'user',$3,$4)",[req.user.sub,v.accountType==='admin'?'admin_access_granted':'admin_access_revoked',id,JSON.stringify({accountType:v.accountType,note:v.note})]);await c.query('COMMIT');res.json(q.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
// Calendar: only reviewed/published events are visible to the public.
app.get('/api/calendar/events',safe(async(req,res)=>{ready();const v=z.object({from:z.string().datetime({offset:true}).optional(),to:z.string().datetime({offset:true}).optional(),kind:z.string().max(32).optional()}).parse(req.query);const from=v.from||new Date().toISOString();const to=v.to||new Date(Date.now()+1000*60*60*24*400).toISOString();if(new Date(to)<=new Date(from))return res.status(400).json({error:'invalid_date_range'});const q=await pool.query("SELECT e.id,e.title,e.description,e.event_kind,e.starts_at,e.ends_at,e.hijri_date_label,e.date_variation_note,e.calendar_method,s.title AS source_title FROM qayyum.calendar_events e LEFT JOIN qayyum.sources s ON s.id=e.source_id WHERE e.publication_status='published' AND (e.starts_at IS NULL OR e.starts_at >= $1::timestamptz) AND (e.starts_at IS NULL OR e.starts_at <= $2::timestamptz) AND ($3::text IS NULL OR e.event_kind=$3) ORDER BY e.starts_at NULLS LAST,e.title LIMIT 500",[from,to,v.kind||null]);res.json({items:q.rows})}));
app.post('/api/calendar/events/suggest',auth,safe(async(req,res)=>{ready();const v=z.object({title:z.string().min(2).max(300),description:z.string().max(12000).optional(),eventKind:z.string().min(2).max(32),startsAt:z.string().datetime({offset:true}).optional(),endsAt:z.string().datetime({offset:true}).optional(),hijriDateLabel:z.string().max(80).optional(),dateVariationNote:z.string().max(5000).optional(),sourceId:z.string().uuid().optional(),calendarMethod:z.string().max(80).optional()}).parse(req.body);if(v.startsAt&&v.endsAt&&new Date(v.endsAt)<new Date(v.startsAt))return res.status(400).json({error:'end_before_start'});const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query("INSERT INTO qayyum.calendar_events(title,description,event_kind,starts_at,ends_at,hijri_date_label,date_variation_note,source_id,publication_status,calendar_method) VALUES($1,$2,$3,$4,$5,$6,$7,$8,'pending',$9) RETURNING id,title,publication_status",[v.title,v.description||null,v.eventKind,v.startsAt||null,v.endsAt||null,v.hijriDateLabel||null,v.dateVariationNote||null,v.sourceId||null,v.calendarMethod||null]);await c.query("INSERT INTO qayyum.owner_approval_queue(submitted_by,request_kind,target_kind,target_id,status) VALUES($1,'publish_calendar_event','calendar_event',$2,'pending')",[req.user.sub,q.rows[0].id]);await c.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'calendar_event_submitted','calendar_event',$2,$3)",[req.user.sub,q.rows[0].id,JSON.stringify({title:v.title})]);await c.query('COMMIT');res.status(202).json({...q.rows[0],message:'event_submitted_for_owner_review'})}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.get('/api/admin/calendar/events',auth,admin,safe(async(_req,res)=>{ready();const q=await pool.query("SELECT e.id,e.title,e.event_kind,e.starts_at,e.hijri_date_label,e.publication_status,e.reviewed_at,p.display_name AS submitter FROM qayyum.calendar_events e LEFT JOIN qayyum.owner_approval_queue a ON a.target_id=e.id::text AND a.target_kind='calendar_event' LEFT JOIN qayyum.user_profiles p ON p.user_id=a.submitted_by WHERE e.publication_status IN ('pending','draft') ORDER BY e.reviewed_at DESC NULLS FIRST,e.starts_at DESC NULLS LAST LIMIT 300");res.json({items:q.rows})}));
app.put('/api/admin/calendar/events/:id/decision',auth,admin,safe(async(req,res)=>{ready();if(req.user.account_type!=='owner')return res.status(403).json({error:'owner_approval_required'});const id=z.string().uuid().parse(req.params.id);const v=z.object({decision:z.enum(['publish','return','withdraw']),note:z.string().min(3).max(3000)}).parse(req.body);const status={publish:'published',return:'draft',withdraw:'withdrawn'}[v.decision];const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query('UPDATE qayyum.calendar_events SET publication_status=$2,reviewed_by=$3,reviewed_at=now() WHERE id=$1 AND publication_status IN (\'pending\',\'draft\') RETURNING id,title,publication_status',[id,status,req.user.sub]);if(!q.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'calendar_event_not_reviewable'})}await c.query("UPDATE qayyum.owner_approval_queue SET status=$2,decision_by=$3,decision_note=$4,decided_at=now() WHERE target_kind='calendar_event' AND target_id=$1 AND status IN ('pending','returned')",[id,v.decision==='publish'?'approved':v.decision==='return'?'returned':'rejected',req.user.sub,v.note]);await c.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'calendar_event_decision','calendar_event',$2,$3)",[req.user.sub,id,JSON.stringify({decision:v.decision,note:v.note})]);await c.query('COMMIT');res.json(q.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
// In-app notifications and per-user calendar/notification preferences.
app.get('/api/notifications',auth,safe(async(req,res)=>{ready();const limit=Math.min(100,Math.max(1,Number(req.query.limit)||50));const q=await pool.query('SELECT id,notification_kind,priority,title,body,target_url,read_at,created_at FROM qayyum.notifications WHERE user_id=$1 ORDER BY created_at DESC LIMIT $2',[req.user.sub,limit]);const unread=await pool.query('SELECT count(*)::int AS count FROM qayyum.notifications WHERE user_id=$1 AND read_at IS NULL',[req.user.sub]);res.json({items:q.rows,unreadCount:unread.rows[0].count})}));
app.put('/api/notifications/:id/read',auth,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const q=await pool.query('UPDATE qayyum.notifications SET read_at=COALESCE(read_at,now()) WHERE id=$1 AND user_id=$2 RETURNING id,read_at',[id,req.user.sub]);if(!q.rowCount)return res.status(404).json({error:'notification_not_found'});res.json(q.rows[0])}));
app.put('/api/notifications/read-all',auth,safe(async(req,res)=>{ready();const q=await pool.query('UPDATE qayyum.notifications SET read_at=now() WHERE user_id=$1 AND read_at IS NULL RETURNING id',[req.user.sub]);res.json({markedRead:q.rowCount})}));
app.get('/api/preferences/platform',auth,safe(async(req,res)=>{ready();const q=await pool.query('SELECT interface_language,text_direction,calendar_default,calendar_authority_mode,timezone,profile_visibility,accessibility FROM qayyum.user_platform_preferences WHERE user_id=$1',[req.user.sub]);const n=await pool.query('SELECT notification_kind,in_app_enabled,browser_enabled,mobile_enabled,email_enabled,quiet_hours FROM qayyum.notification_preferences WHERE user_id=$1 ORDER BY notification_kind',[req.user.sub]);res.json({platform:q.rows[0]||null,notifications:n.rows})}));
app.put('/api/preferences/platform',auth,safe(async(req,res)=>{ready();const v=z.object({interfaceLanguage:z.string().min(2).max(32).optional(),textDirection:z.enum(['rtl','ltr']).optional(),calendarDefault:z.enum(['hijri','gregorian']).optional(),calendarAuthorityMode:z.string().min(2).max(32).optional(),timezone:z.string().max(80).optional(),profileVisibility:z.enum(['public','private']).optional(),accessibility:z.record(z.any()).optional(),notificationPreferences:z.array(z.object({kind:z.string().min(1).max(48),inApp:z.boolean().optional(),browser:z.boolean().optional(),mobile:z.boolean().optional(),email:z.boolean().optional()})).max(30).optional()}).parse(req.body);const c=await pool.connect();try{await c.query('BEGIN');await c.query("INSERT INTO qayyum.user_platform_preferences(user_id,interface_language,text_direction,calendar_default,calendar_authority_mode,timezone,profile_visibility,accessibility) VALUES($1,COALESCE($2,'ar'),COALESCE($3,'rtl'),COALESCE($4,'hijri'),COALESCE($5,'show_variations'),$6,COALESCE($7,'public'),COALESCE($8,'{}'::jsonb)) ON CONFLICT(user_id) DO UPDATE SET interface_language=COALESCE($2,user_platform_preferences.interface_language),text_direction=COALESCE($3,user_platform_preferences.text_direction),calendar_default=COALESCE($4,user_platform_preferences.calendar_default),calendar_authority_mode=COALESCE($5,user_platform_preferences.calendar_authority_mode),timezone=COALESCE($6,user_platform_preferences.timezone),profile_visibility=COALESCE($7,user_platform_preferences.profile_visibility),accessibility=COALESCE($8,user_platform_preferences.accessibility),updated_at=now()",[req.user.sub,v.interfaceLanguage,v.textDirection,v.calendarDefault,v.calendarAuthorityMode,v.timezone||null,v.profileVisibility,v.accessibility?JSON.stringify(v.accessibility):null]);for(const n of v.notificationPreferences||[])await c.query('INSERT INTO qayyum.notification_preferences(user_id,notification_kind,in_app_enabled,browser_enabled,mobile_enabled,email_enabled) VALUES($1,$2,COALESCE($3,true),COALESCE($4,false),COALESCE($5,false),COALESCE($6,false)) ON CONFLICT(user_id,notification_kind) DO UPDATE SET in_app_enabled=EXCLUDED.in_app_enabled,browser_enabled=EXCLUDED.browser_enabled,mobile_enabled=EXCLUDED.mobile_enabled,email_enabled=EXCLUDED.email_enabled,updated_at=now()',[req.user.sub,n.kind,n.inApp,n.browser,n.mobile,n.email]);await c.query('COMMIT');res.json({saved:true})}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.post('/api/admin/import/preview',auth,admin,safe(async(req,res)=>{ready();const schema=z.object({sourceCode:z.string().min(3).max(40),batchName:z.string().min(1).max(240),records:z.array(z.object({sourceRecordId:z.string().min(1).max(500),title:z.string().min(1).max(500),author:z.string().max(300).optional(),language:z.string().max(16).optional(),raw:z.record(z.any()).default({})})).max(5000)});const v=schema.parse(req.body);const seen=new Set();const preview=v.records.map((x,i)=>{const key=x.sourceRecordId;const duplicate=seen.has(key);seen.add(key);return {row:i+1,sourceRecordId:key,valid:!duplicate,title:x.title,author:x.author||null,action:duplicate?'reject_duplicate':'stage_only'}});res.json({total:preview.length,stageable:preview.filter(x=>x.valid).length,rejected:preview.filter(x=>!x.valid).length,published:0,records:preview})}));
app.post('/api/admin/import/stage',auth,admin,safe(async(req,res)=>{ready();const schema=z.object({sourceCode:z.string().min(3).max(40),batchName:z.string().min(1).max(240),records:z.array(z.object({sourceRecordId:z.string().min(1).max(500),sourceRecordUrl:z.string().url().optional(),title:z.string().min(1).max(500),author:z.string().max(300).optional(),language:z.string().max(16).optional(),raw:z.record(z.any()).default({})})).min(1).max(5000)});const v=schema.parse(req.body);const c=await pool.connect();try{await c.query('BEGIN');const src=await c.query('SELECT id FROM qayyum.catalog_sources WHERE source_code=$1 AND enabled=true',[v.sourceCode]);if(!src.rowCount)throw Object.assign(new Error('unknown_or_disabled_source'),{status:400});const batch=await c.query("INSERT INTO qayyum.catalog_import_batches(source_id,batch_name,status,records_seen,created_by) VALUES($1,$2,'validating',$3,$4) RETURNING id",[src.rows[0].id,v.batchName,v.records.length,req.user.sub]);let staged=0,duplicates=0;for(const r of v.records){const exists=await c.query('SELECT 1 FROM qayyum.import_idempotency WHERE source_id=$1 AND source_record_id=$2',[src.rows[0].id,r.sourceRecordId]);if(exists.rowCount){duplicates++;continue}await c.query("INSERT INTO qayyum.catalog_import_records(batch_id,source_id,source_record_id,source_record_url,raw_record,normalized_title,normalized_author,verification_status) VALUES($1,$2,$3,$4,$5,$6,$7,'unverified')",[batch.rows[0].id,src.rows[0].id,r.sourceRecordId,r.sourceRecordUrl||null,JSON.stringify(r.raw),r.title,r.author||null]);await c.query('INSERT INTO qayyum.import_idempotency(source_id,source_record_id,payload_sha256,last_batch_id) VALUES($1,$2,$3,$4)',[src.rows[0].id,r.sourceRecordId,crypto.createHash('sha256').update(JSON.stringify(r.raw)).digest('hex'),batch.rows[0].id]);staged++}await c.query("UPDATE qayyum.catalog_import_batches SET status='needs_review',records_valid=$2,records_duplicate=$3,completed_at=now() WHERE id=$1",[batch.rows[0].id,staged,duplicates]);await c.query("INSERT INTO qayyum.import_batch_audit(batch_id,actor_user_id,event_code,details) VALUES($1,$2,'batch_staged',$3)",[batch.rows[0].id,req.user.sub,JSON.stringify({staged,duplicates})]);await c.query('COMMIT');res.status(201).json({batchId:batch.rows[0].id,staged,duplicates,published:0,status:'needs_review'})}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.post('/api/admin/import/records/:id/approve',auth,admin,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query("SELECT * FROM qayyum.catalog_import_records WHERE id=$1 AND verification_status='unverified' FOR UPDATE",[id]);if(!q.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'record_not_reviewable'})}const r=q.rows[0];const raw=r.raw_record||{};const title=r.normalized_title;const author=r.normalized_author;const w=await c.query("INSERT INTO qayyum.works(canonical_title,language_code,attribution_status,publication_status) VALUES($1,$2,'unverified','draft') RETURNING id",[title,raw.language||'ar']);if(author){const a=await c.query("INSERT INTO qayyum.authors(canonical_name,identity_status) VALUES($1,'unverified') RETURNING id",[author]);await c.query("INSERT INTO qayyum.work_authors(work_id,author_id,contribution) VALUES($1,$2,'author')",[w.rows[0].id,a.rows[0].id])}await c.query("INSERT INTO qayyum.work_provenance(work_id,catalog_source_id,source_record_id,source_record_url,source_snapshot,source_checksum) VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT DO NOTHING",[w.rows[0].id,r.source_id,r.source_record_id,r.source_record_url,JSON.stringify(raw),crypto.createHash('sha256').update(JSON.stringify(raw)).digest('hex')]);await c.query("UPDATE qayyum.catalog_import_records SET verification_status='needs_review',reviewed_by=$2,reviewed_at=now(),imported_work_id=$3 WHERE id=$1",[id,req.user.sub,w.rows[0].id]);await c.query("INSERT INTO qayyum.import_batch_audit(batch_id,actor_user_id,event_code,details) VALUES($1,$2,'record_accepted_to_draft',$3)",[r.batch_id,req.user.sub,JSON.stringify({recordId:id,workId:w.rows[0].id})]);await c.query('COMMIT');res.status(201).json({workId:w.rows[0].id,publicationStatus:'draft',message:'Created a draft only; separate scientific and rights approval required.'})}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.get('/api/files/:id/read',auth,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const q=await pool.query("SELECT f.object_key,f.mime_type,f.original_filename,p.scan_status FROM qayyum.digital_files f JOIN qayyum.private_file_objects p ON p.digital_file_id=f.id WHERE f.id=$1 AND p.scan_status='clean' AND EXISTS(SELECT 1 FROM qayyum.rights_reviews r WHERE r.file_id=f.id AND r.id=(SELECT rr.id FROM qayyum.rights_reviews rr WHERE rr.file_id=f.id ORDER BY rr.reviewed_at DESC NULLS LAST,rr.id DESC LIMIT 1) AND r.decision IN ('approve_reading','approve_distribution') AND r.reviewer_id IS NOT NULL AND r.reviewed_at IS NOT NULL AND (r.expires_at IS NULL OR r.expires_at>=CURRENT_DATE) AND ((r.access_status='open_access' AND r.rights_status IN ('public_domain','licensed')) OR p.uploaded_by=$2 OR $3 IN ('owner','admin')))",[id,req.user.sub,req.user.account_type]);if(!q.rowCount)return res.status(403).json({error:'file_not_cleared_for_reading'});res.type(q.rows[0].mime_type);res.set('Content-Disposition',`inline; filename*=UTF-8''${encodeURIComponent(q.rows[0].original_filename||'book')}`);res.set('X-Content-Type-Options','nosniff');const body=await objectStorage.get(q.rows[0].object_key);await pipeline(body,res)}));
app.get('/api/catalog/works',safe(async(req,res)=>{ready();const v=z.object({q:z.string().max(160).optional().default(''),author:z.string().max(160).optional().default(''),school:z.string().max(100).optional().default(''),category:z.string().max(160).optional().default(''),language:z.string().max(16).optional().default(''),type:z.string().max(40).optional().default('')}).parse(req.query);const rows=await pool.query(`SELECT w.id,w.canonical_title,w.original_title,w.alternate_titles,w.description,w.language_code,w.work_type,w.attribution_status,w.identity_review_status,coalesce(json_agg(DISTINCT a.canonical_name) FILTER(WHERE a.id IS NOT NULL),'[]') authors,(SELECT count(*)::int FROM qayyum.editions e WHERE e.work_id=w.id AND e.review_status='approved') edition_count FROM qayyum.works w LEFT JOIN qayyum.work_authors wa ON wa.work_id=w.id LEFT JOIN qayyum.authors a ON a.id=wa.author_id WHERE w.publication_status='approved' AND ($1='' OR w.canonical_title ILIKE '%'||$1||'%' OR w.original_title ILIKE '%'||$1||'%' OR EXISTS(SELECT 1 FROM unnest(w.alternate_titles) t WHERE t ILIKE '%'||$1||'%')) AND ($2='' OR EXISTS(SELECT 1 FROM qayyum.work_authors x JOIN qayyum.authors y ON y.id=x.author_id WHERE x.work_id=w.id AND y.canonical_name ILIKE '%'||$2||'%')) AND ($3='' OR EXISTS(SELECT 1 FROM qayyum.work_schools ws JOIN qayyum.schools sc ON sc.id=ws.school_id WHERE ws.work_id=w.id AND (sc.name ILIKE '%'||$3||'%' OR sc.code=$3))) AND ($4='' OR EXISTS(SELECT 1 FROM qayyum.work_categories wc JOIN qayyum.categories c ON c.id=wc.category_id WHERE wc.work_id=w.id AND (c.name ILIKE '%'||$4||'%' OR c.slug=$4))) AND ($5='' OR w.language_code=$5) AND ($6='' OR w.work_type=$6) GROUP BY w.id ORDER BY w.canonical_title LIMIT 100`,[v.q,v.author,v.school,v.category,v.language,v.type]);res.json({items:rows.rows})}));
app.get('/api/catalog/works/:id',safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const w=await pool.query("SELECT w.id,w.canonical_title,w.original_title,w.alternate_titles,w.description,w.language_code,w.work_type,w.attribution_status,w.identity_review_status,coalesce(json_agg(DISTINCT a.canonical_name) FILTER(WHERE a.id IS NOT NULL),'[]') authors FROM qayyum.works w LEFT JOIN qayyum.work_authors wa ON wa.work_id=w.id LEFT JOIN qayyum.authors a ON a.id=wa.author_id WHERE w.id=$1 AND w.publication_status='approved' GROUP BY w.id",[id]);if(!w.rowCount)return res.status(404).json({error:'work_not_found'});const editions=await pool.query("SELECT id,edition_title,editor_name,translator_name,edition_number,publication_year_text,publication_place,volume_count,page_count,edition_language,digital_format,digital_access_status FROM qayyum.editions WHERE work_id=$1 AND review_status='approved' ORDER BY publication_year_text DESC NULLS LAST",[id]);res.json({work:w.rows[0],editions:editions.rows})}));
