app.post('/api/admin/rijal/narrators',auth,admin,safe(async(req,res)=>{ready();const v=z.object({name:z.string().trim().min(2).max(300),biography:z.string().max(30000).optional(),identityStatus:z.enum(['verified','under_review','disputed','unverified']).default('unverified'),alternateNames:z.array(z.string().trim().min(2).max(300)).max(30).default([])}).parse(req.body);const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query('INSERT INTO qayyum.narrators(canonical_name,biography,identity_status) VALUES($1,$2,$3) RETURNING id,canonical_name,identity_status',[v.name,v.biography||null,v.identityStatus]);for(const name of new Set(v.alternateNames))await c.query("INSERT INTO qayyum.narrator_names(narrator_id,name,name_kind) VALUES($1,$2,'alternate')",[q.rows[0].id,name]);await c.query('COMMIT');res.status(201).json(q.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.post('/api/admin/rijal/narrators/:id/assessments',auth,admin,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({scholar:z.string().trim().min(2).max(300),text:z.string().trim().min(3).max(12000),status:z.enum(['verified','needs_review','disputed']).default('needs_review'),editionId:z.string().uuid().optional(),volume:z.string().max(80).optional(),page:z.string().max(80).optional()}).parse(req.body);if(v.editionId){const e=await pool.query("SELECT id FROM qayyum.editions WHERE id=$1 AND review_status='approved'",[v.editionId]);if(!e.rowCount)return res.status(400).json({error:'catalog_edition_not_approved'})}const q=await pool.query('INSERT INTO qayyum.narrator_assessments(narrator_id,scholar_name,assessment_text,assessment_status,edition_id,volume_label,page_label) SELECT id,$2,$3,$4,$5,$6,$7 FROM qayyum.narrators WHERE id=$1 RETURNING id,narrator_id,scholar_name,assessment_status',[id,v.scholar,v.text,v.status,v.editionId||null,v.volume||null,v.page||null]);if(!q.rowCount)return res.status(404).json({error:'narrator_not_found'});res.status(201).json(q.rows[0])}));
app.post('/api/admin/hadith/variants/:id/isnads',auth,admin,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({routeLabel:z.string().max(200).optional(),note:z.string().max(5000).optional(),sourceId:z.string().uuid().optional(),editionId:z.string().uuid().optional(),narrators:z.array(z.object({narratorId:z.string().uuid(),transmission:z.string().max(120).optional()})).min(1).max(100)}).parse(req.body);const c=await pool.connect();try{await c.query('BEGIN');const variant=await c.query('SELECT id FROM qayyum.hadith_variants WHERE id=$1 FOR UPDATE',[id]);if(!variant.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'hadith_variant_not_found'})}const valid=await c.query('SELECT id FROM qayyum.narrators WHERE id=ANY($1::uuid[])',[v.narrators.map(x=>x.narratorId)]);if(valid.rowCount!==new Set(v.narrators.map(x=>x.narratorId)).size){await c.query('ROLLBACK');return res.status(400).json({error:'unknown_narrator'})}const chain=await c.query('INSERT INTO qayyum.isnads(variant_id,source_id,edition_id,chain_note,route_label) VALUES($1,$2,$3,$4,$5) RETURNING id',[id,v.sourceId||null,v.editionId||null,v.note||null,v.routeLabel||null]);for(let i=0;i<v.narrators.length;i++)await c.query('INSERT INTO qayyum.isnad_links(isnad_id,sequence_no,narrator_id,transmission_wording) VALUES($1,$2,$3,$4)',[chain.rows[0].id,i+1,v.narrators[i].narratorId,v.narrators[i].transmission||null]);await c.query('COMMIT');res.status(201).json({id:chain.rows[0].id,linkedNarrators:v.narrators.length})}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.get('/api/hadith/reports',auth,safe(async(req,res)=>{ready();const v=z.object({q:z.string().trim().max(500).default(''),narrator:z.string().trim().max(300).default(''),source:z.string().trim().max(300).default(''),limit:z.coerce.number().int().min(1).max(50).default(20)}).parse(req.query);if(v.q.length<2&&!v.narrator&&!v.source)return res.json({items:[],notice:'أدخل عبارة بحث أو راوياً أو مصدراً.'});const q=await pool.query(`SELECT DISTINCT h.id,h.canonical_text,h.text_status,h.topic_tags,h.created_at,COUNT(DISTINCT hv.id)::int AS variant_count,COALESCE(json_agg(DISTINCT jsonb_build_object('title',w.canonical_title,'volume',hv.volume_label,'page',hv.page_label,'number',hv.hadith_number)) FILTER(WHERE hv.id IS NOT NULL),'[]'::json) AS source_references FROM qayyum.hadith_reports h LEFT JOIN qayyum.hadith_variants hv ON hv.report_id=h.id LEFT JOIN qayyum.editions e ON e.id=hv.edition_id LEFT JOIN qayyum.works w ON w.id=e.work_id LEFT JOIN qayyum.isnads i ON i.variant_id=hv.id LEFT JOIN qayyum.isnad_links il ON il.isnad_id=i.id LEFT JOIN qayyum.narrators n ON n.id=il.narrator_id WHERE ($1='' OR h.canonical_text ILIKE '%'||$1||'%' OR EXISTS(SELECT 1 FROM unnest(h.topic_tags) t WHERE t ILIKE '%'||$1||'%')) AND ($2='' OR EXISTS(SELECT 1 FROM qayyum.isnad_links x JOIN qayyum.narrators y ON y.id=x.narrator_id WHERE x.isnad_id=i.id AND y.canonical_name ILIKE '%'||$2||'%')) AND ($3='' OR w.canonical_title ILIKE '%'||$3||'%') GROUP BY h.id ORDER BY h.created_at DESC LIMIT $4`,[v.q,v.narrator,v.source,v.limit]);res.json({items:q.rows})}));
app.get('/api/hadith/reports/:id',auth,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const h=await pool.query('SELECT id,canonical_text,text_status,topic_tags,created_at FROM qayyum.hadith_reports WHERE id=$1',[id]);if(!h.rowCount)return res.status(404).json({error:'hadith_not_found'});const [variants,grades]=await Promise.all([pool.query(`SELECT hv.id,hv.wording,hv.volume_label,hv.page_label,hv.hadith_number,hv.verification_status,w.canonical_title AS work_title,e.edition_title,p.name AS publisher FROM qayyum.hadith_variants hv LEFT JOIN qayyum.editions e ON e.id=hv.edition_id LEFT JOIN qayyum.works w ON w.id=e.work_id LEFT JOIN qayyum.publishers p ON p.id=e.publisher_id WHERE hv.report_id=$1 ORDER BY hv.id`,[id]),pool.query(`SELECT g.scholar_name,g.grade_label,g.explanation,g.verification_status,w.canonical_title AS work_title,e.edition_title,g.volume_label,g.page_label FROM qayyum.hadith_grades g LEFT JOIN qayyum.editions e ON e.id=g.edition_id LEFT JOIN qayyum.works w ON w.id=e.work_id WHERE g.report_id=$1 ORDER BY g.scholar_name`,[id])]);const chains=[];for(const v of variants.rows){const q=await pool.query(`SELECT i.id,i.route_label,i.chain_note,COALESCE(json_agg(json_build_object('sequence',il.sequence_no,'name',n.canonical_name,'transmission',il.transmission_wording) ORDER BY il.sequence_no) FILTER(WHERE n.id IS NOT NULL),'[]'::json) AS narrators FROM qayyum.isnads i LEFT JOIN qayyum.isnad_links il ON il.isnad_id=i.id LEFT JOIN qayyum.narrators n ON n.id=il.narrator_id WHERE i.variant_id=$1 GROUP BY i.id ORDER BY i.id`,[v.id]);chains.push(...q.rows)}res.json({report:h.rows[0],variants:variants.rows,isnads:chains,grades:grades.rows})}));
app.get('/api/rijal/narrators',auth,safe(async(req,res)=>{ready();const v=z.object({q:z.string().trim().min(2).max(300),limit:z.coerce.number().int().min(1).max(50).default(30)}).parse(req.query);const q=await pool.query(`SELECT n.id,n.canonical_name,n.identity_status,n.biography,COALESCE(array_agg(DISTINCT nn.name) FILTER(WHERE nn.name IS NOT NULL),'{}') AS alternate_names FROM qayyum.narrators n LEFT JOIN qayyum.narrator_names nn ON nn.narrator_id=n.id WHERE n.canonical_name ILIKE '%'||$1||'%' OR EXISTS(SELECT 1 FROM qayyum.narrator_names x WHERE x.narrator_id=n.id AND x.name ILIKE '%'||$1||'%') GROUP BY n.id ORDER BY n.canonical_name LIMIT $2`,[v.q,v.limit]);res.json({items:q.rows})}));
app.get('/api/rijal/narrators/:id',auth,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const n=await pool.query('SELECT id,canonical_name,identity_status,biography FROM qayyum.narrators WHERE id=$1',[id]);if(!n.rowCount)return res.status(404).json({error:'narrator_not_found'});const [names,assessments,chains]=await Promise.all([pool.query('SELECT name,name_kind FROM qayyum.narrator_names WHERE narrator_id=$1 ORDER BY name',[id]),pool.query(`SELECT a.scholar_name,a.assessment_text,a.assessment_status,a.volume_label,a.page_label,w.canonical_title AS work_title,e.edition_title FROM qayyum.narrator_assessments a LEFT JOIN qayyum.editions e ON e.id=a.edition_id LEFT JOIN qayyum.works w ON w.id=e.work_id WHERE a.narrator_id=$1 ORDER BY a.scholar_name`,[id]),pool.query(`SELECT h.id AS report_id,h.canonical_text,i.route_label,il.sequence_no FROM qayyum.isnad_links il JOIN qayyum.isnads i ON i.id=il.isnad_id JOIN qayyum.hadith_variants hv ON hv.id=i.variant_id JOIN qayyum.hadith_reports h ON h.id=hv.report_id WHERE il.narrator_id=$1 ORDER BY h.created_at DESC LIMIT 100`,[id])]);res.json({narrator:n.rows[0],names:names.rows,assessments:assessments.rows,appearances:chains.rows})}));
