app.post('/api/admin/hadith/reports/:id/grades',auth,admin,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({scholar:z.string().trim().min(2).max(300),grade:z.string().trim().min(1).max(120),explanation:z.string().max(12000).optional(),editionId:z.string().uuid().optional(),volume:z.string().max(80).optional(),page:z.string().max(80).optional(),status:z.enum(['verified','unverified','disputed']).default('unverified')}).parse(req.body);if(v.editionId){const e=await pool.query("SELECT id FROM qayyum.editions WHERE id=$1 AND review_status='approved'",[v.editionId]);if(!e.rowCount)return res.status(400).json({error:'catalog_edition_not_approved'})}const q=await pool.query('INSERT INTO qayyum.hadith_grades(report_id,scholar_name,grade_label,explanation,edition_id,volume_label,page_label,verification_status) SELECT id,$2,$3,$4,$5,$6,$7,$8 FROM qayyum.hadith_reports WHERE id=$1 RETURNING id,scholar_name,grade_label,verification_status',[id,v.scholar,v.grade,v.explanation||null,v.editionId||null,v.volume||null,v.page||null,v.status]);if(!q.rowCount)return res.status(404).json({error:'hadith_not_found'});res.status(201).json(q.rows[0])}));
app.get('/api/manuscripts',auth,safe(async(req,res)=>{ready();const q=z.string().trim().max(300).default('').parse(String(req.query.q||''));const status=req.user.account_type==='owner'||req.user.account_type==='admin'?'approved':'approved';const r=await pool.query(`SELECT id,title,author_name,repository_name,collection_code,shelfmark,manuscript_date,copyist_name,language_code,folio_count,description,catalogue_url,rights_status FROM qayyum.manuscript_witnesses WHERE review_status=$2 AND ($1='' OR title ILIKE '%'||$1||'%' OR coalesce(author_name,'') ILIKE '%'||$1||'%' OR repository_name ILIKE '%'||$1||'%' OR coalesce(shelfmark,'') ILIKE '%'||$1||'%') ORDER BY title LIMIT 100`,[q,status]);res.json({items:r.rows})}));
