app.get('/api/catalog/editions',auth,safe(async(req,res)=>{ready();const q=z.string().trim().max(200).default('').parse(String(req.query.q||''));if(q.length<2)return res.json({items:[]});const r=await pool.query(`SELECT e.id AS edition_id,w.id AS work_id,w.canonical_title,e.edition_title,e.editor_name,e.edition_number,e.publication_year_text,e.volume_count,p.name AS publisher_name,COALESCE(array_agg(DISTINCT a.canonical_name) FILTER(WHERE a.id IS NOT NULL),'{}') AS authors FROM qayyum.editions e JOIN qayyum.works w ON w.id=e.work_id LEFT JOIN qayyum.publishers p ON p.id=e.publisher_id LEFT JOIN qayyum.work_authors wa ON wa.work_id=w.id LEFT JOIN qayyum.authors a ON a.id=wa.author_id WHERE e.review_status='approved' AND w.publication_status='approved' AND (w.canonical_title ILIKE '%'||$1||'%' OR EXISTS(SELECT 1 FROM qayyum.work_authors x JOIN qayyum.authors y ON y.id=x.author_id WHERE x.work_id=w.id AND y.canonical_name ILIKE '%'||$1||'%')) GROUP BY e.id,w.id,p.name ORDER BY w.canonical_title LIMIT 30`,[q]);res.json({items:r.rows})}));
