const upload=multer({storage:multer.memoryStorage(),limits:{fileSize:max,files:1},fileFilter:(_req,file,cb)=>{const ok=/\.(pdf|epub)$/i.test(file.originalname);cb(ok?null:Object.assign(new Error('Only PDF and EPUB are accepted'),{status:415}),ok)}});

const profileUpload=multer({storage:multer.memoryStorage(),limits:{fileSize:5*1024*1024,files:1},fileFilter:(_req,file,cb)=>{const ok=['image/jpeg','image/png','image/webp'].includes(file.mimetype);cb(ok?null:Object.assign(new Error('Only PNG, JPEG and WEBP images are accepted'),{status:415}),ok)}});
app.get('/api/profile',auth,safe(async(req,res)=>{ready();const q=await pool.query('SELECT p.display_name,p.username,p.biography,p.preferred_language,p.timezone,p.avatar_object_key FROM qayyum.user_profiles p WHERE p.user_id=$1',[req.user.sub]);const p=q.rows[0]||{};res.json({displayName:p.display_name||'',username:p.username||'',biography:p.biography||'',preferredLanguage:p.preferred_language||'ar',timezone:p.timezone||'',hasAvatar:!!p.avatar_object_key})}));
app.patch('/api/profile',auth,safe(async(req,res)=>{ready();const v=z.object({displayName:z.string().trim().min(2).max(160).optional(),username:z.string().trim().max(32).regex(/^[A-Za-z0-9_]{3,32}$/).optional().or(z.literal('')),biography:z.string().max(2000).optional(),preferredLanguage:z.string().min(2).max(16).optional(),timezone:z.string().max(64).optional()}).refine(x=>Object.keys(x).length>0).parse(req.body);const username=v.username===undefined?null:(v.username?v.username.toLowerCase():null);const c=await pool.connect();try{await c.query('BEGIN');await c.query(`INSERT INTO qayyum.user_profiles(user_id,display_name,username,biography,preferred_language,timezone) VALUES($1,$2,$3,$4,COALESCE($5,'ar'),$6) ON CONFLICT(user_id) DO UPDATE SET display_name=COALESCE($2,user_profiles.display_name),username=CASE WHEN $7::boolean THEN $3 ELSE user_profiles.username END,biography=CASE WHEN $8::boolean THEN $4 ELSE user_profiles.biography END,preferred_language=COALESCE($5,user_profiles.preferred_language),timezone=CASE WHEN $9::boolean THEN $6 ELSE user_profiles.timezone END,updated_at=now()`,[req.user.sub,v.displayName||null,username,v.biography??null,v.preferredLanguage||null,v.timezone||null,v.username!==undefined,v.biography!==undefined,v.timezone!==undefined]);const q=await c.query('SELECT display_name,username,biography,preferred_language,timezone FROM qayyum.user_profiles WHERE user_id=$1',[req.user.sub]);await c.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'profile_updated','user',$1,$2)",[req.user.sub,JSON.stringify({fields:Object.keys(v)})]);await c.query('COMMIT');const p=q.rows[0];res.json({displayName:p.display_name,username:p.username,biography:p.biography,preferredLanguage:p.preferred_language,timezone:p.timezone})}catch(e){await c.query('ROLLBACK');if(e.code==='23505')return res.status(409).json({error:'username_taken'});throw e}finally{c.release()}}));
app.post('/api/profile/avatar',auth,profileUpload.single('avatar'),safe(async(req,res)=>{ready();if(!req.file)return res.status(400).json({error:'avatar_required'});const b=req.file.buffer,m=req.file.mimetype;const valid=(m==='image/jpeg'&&b[0]===0xff&&b[1]===0xd8&&b[2]===0xff)||(m==='image/png'&&b.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])))||(m==='image/webp'&&b.subarray(0,4).toString()==='RIFF'&&b.subarray(8,12).toString()==='WEBP');if(!valid)return res.status(415).json({error:'avatar_signature_mismatch'});const key=crypto.randomUUID();const stored=await objectStorage.put(key,b,m);const c=await pool.connect();let oldKey=null;try{await c.query('BEGIN');const old=await c.query('SELECT avatar_object_key FROM qayyum.user_profiles WHERE user_id=$1 FOR UPDATE',[req.user.sub]);oldKey=old.rows[0]?.avatar_object_key||null;await c.query(`INSERT INTO qayyum.user_profiles(user_id,avatar_object_key,avatar_mime_type) VALUES($1,$2,$3) ON CONFLICT(user_id) DO UPDATE SET avatar_object_key=$2,avatar_mime_type=$3,updated_at=now()`,[req.user.sub,stored,m]);await c.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'profile_avatar_updated','user',$1,$2)",[req.user.sub,JSON.stringify({mime:m,size:b.length})]);await c.query('COMMIT')}catch(e){await c.query('ROLLBACK');await objectStorage.delete(stored).catch(()=>{});throw e}finally{c.release()}if(oldKey&&oldKey!==stored)await objectStorage.delete(oldKey).catch(()=>{});res.status(201).json({saved:true})}));
app.patch('/api/profile/password',auth,safe(async(req,res)=>{ready();const v=z.object({currentPassword:z.string().min(1).max(72),newPassword:z.string().min(12).max(72).refine(x=>Buffer.byteLength(x,'utf8')<=72,{message:'password_too_long_in_bytes'})}).parse(req.body);if(v.currentPassword===v.newPassword)return res.status(400).json({error:'new_password_must_be_different'});const old=await pool.query("SELECT id,provider_subject,credential_hash FROM qayyum.auth_identities WHERE user_id=$1 AND provider='email'",[req.user.sub]);if(!old.rowCount||!old.rows[0].credential_hash)return res.status(409).json({error:'password_change_unavailable'});if(!await bcrypt.compare(v.currentPassword,old.rows[0].credential_hash))return res.status(401).json({error:'current_password_incorrect'});const hash=await bcrypt.hash(v.newPassword,12);await pool.query("UPDATE qayyum.auth_identities SET credential_hash=$2 WHERE id=$1",[old.rows[0].id,hash]);await pool.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'profile_password_changed','user',$1,'{}'::jsonb)",[req.user.sub]);res.json({changed:true})}));
app.get('/api/profile/avatar',auth,safe(async(req,res)=>{ready();const q=await pool.query('SELECT avatar_object_key,avatar_mime_type FROM qayyum.user_profiles WHERE user_id=$1',[req.user.sub]);if(!q.rowCount||!q.rows[0].avatar_object_key)return res.status(404).json({error:'avatar_not_found'});const stream=await objectStorage.get(q.rows[0].avatar_object_key);res.setHeader('Content-Type',q.rows[0].avatar_mime_type||'application/octet-stream');res.setHeader('Cache-Control','private, no-store');res.setHeader('X-Content-Type-Options','nosniff');stream.on('error',()=>{if(!res.headersSent)res.status(404).end();else res.destroy()});stream.pipe(res)}));
app.delete('/api/profile/avatar',auth,safe(async(req,res)=>{ready();const c=await pool.connect();let oldKey=null;try{await c.query('BEGIN');const old=await c.query('SELECT avatar_object_key FROM qayyum.user_profiles WHERE user_id=$1 FOR UPDATE',[req.user.sub]);oldKey=old.rows[0]?.avatar_object_key||null;await c.query('UPDATE qayyum.user_profiles SET avatar_object_key=NULL,avatar_mime_type=NULL,updated_at=now() WHERE user_id=$1',[req.user.sub]);await c.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'profile_avatar_deleted','user',$1,'{}'::jsonb)",[req.user.sub]);await c.query('COMMIT')}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}if(oldKey)await objectStorage.delete(oldKey).catch(()=>{});res.status(204).end()}));
app.post('/api/files',auth,upload.single('file'),safe(async(req,res)=>{ready();if(process.env.NODE_ENV==='production'&&!durableStorage)return res.status(503).json({error:'durable_private_storage_not_configured'});if(!req.file)return res.status(400).json({error:'file_required'});const b=req.file.buffer;const pdf=b.subarray(0,5).toString()==='%PDF-';const zip=b[0]===0x50&&b[1]===0x4b;const ext=path.extname(req.file.originalname).toLowerCase();if(!((ext==='.pdf'&&pdf)||(ext==='.epub'&&zip)))return res.status(415).json({error:'file_signature_mismatch'});const hash=crypto.createHash('sha256').update(b).digest('hex');const key=crypto.randomUUID();const mime=pdf?'application/pdf':'application/epub+zip';const storageKey=(await objectStorage.put(key,b,mime))||key;const c=await pool.connect();try{await c.query('BEGIN');const f=await c.query("INSERT INTO qayyum.digital_files(object_key,original_filename,mime_type,file_size_bytes,checksum_sha256,file_role,technical_status) VALUES($1,$2,$3,$4,$5,'full_text','pending') RETURNING id",[storageKey,req.file.originalname.slice(0,500),mime,b.length,hash]);await c.query("INSERT INTO qayyum.private_file_objects(digital_file_id,storage_key,uploaded_by,detected_mime,sha256,size_bytes,scan_status) VALUES($1,$2,$3,$4,$5,$6,'pending')",[f.rows[0].id,storageKey,req.user.sub,mime,hash,b.length]);await c.query("INSERT INTO qayyum.rights_reviews(file_id,rights_status,access_status,decision,notes) VALUES($1,'unknown','unknown','hold','Automatic quarantine: human rights review required before any reading or distribution.')",[f.rows[0].id]);await c.query('COMMIT');res.status(202).json({status:'quarantined_pending_scan_and_rights_review',fileId:f.rows[0].id,storageKey,sha256:hash,size:b.length,mime,message:'Private storage only. No public URL until malware and rights review pass.'})}catch(e){await c.query('ROLLBACK');await objectStorage.delete(storageKey).catch(()=>{});throw e}finally{c.release()}}));
app.get('/api/admin/files/:id/quarantine',auth,admin,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const q=await pool.query('SELECT f.object_key,f.original_filename,p.scan_status FROM qayyum.digital_files f JOIN qayyum.private_file_objects p ON p.digital_file_id=f.id WHERE f.id=$1',[id]);if(!q.rowCount)return res.status(404).json({error:'file_not_found'});res.type('application/octet-stream');res.set('Content-Disposition',`attachment; filename*=UTF-8''${encodeURIComponent((q.rows[0].original_filename||'quarantined-file').replaceAll(String.fromCharCode(10),'').replaceAll(String.fromCharCode(13),''))}.quarantine`);res.set('X-Content-Type-Options','nosniff');res.set('Cache-Control','no-store');res.set('X-File-Scan-Status',q.rows[0].scan_status);await pipeline(await objectStorage.get(q.rows[0].object_key),res)}));
app.put('/api/admin/files/:id/review',auth,admin,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({scanStatus:z.enum(['clean','rejected','infected','error']),rightsStatus:z.enum(['public_domain','licensed','reading_only','permission_required','unknown','prohibited']),accessStatus:z.enum(['metadata_only','open_access','controlled','restricted','unknown']),decision:z.enum(['approve_metadata_only','approve_reading','approve_distribution','reject','hold']),licenseName:z.string().max(500).optional(),licenseUrl:z.string().url().optional(),licenseText:z.string().max(20000).optional(),rightsHolder:z.string().max(500).optional(),notes:z.string().max(5000).optional(),expiresAt:z.string().date().optional()}).parse(req.body);if(['approve_reading','approve_distribution'].includes(v.decision)&&v.scanStatus!=='clean')return res.status(400).json({error:'file_must_pass_malware_review_before_access_approval'});if(v.decision==='approve_distribution'&&(!['public_domain','licensed'].includes(v.rightsStatus)||!v.licenseName||!v.licenseUrl||!v.licenseText))return res.status(400).json({error:'distribution_requires_documented_rights'});if(v.decision==='approve_reading'&&(!['public_domain','licensed','reading_only'].includes(v.rightsStatus)||!v.licenseUrl))return res.status(400).json({error:'reading_not_permitted_by_rights_status'});const c=await pool.connect();try{await c.query('BEGIN');const f=await c.query('SELECT id FROM qayyum.digital_files WHERE id=$1 FOR UPDATE',[id]);if(!f.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'file_not_found'})}await c.query('UPDATE qayyum.private_file_objects SET scan_status=$2 WHERE digital_file_id=$1',[id,v.scanStatus]);await c.query('UPDATE qayyum.digital_files SET technical_status=$2 WHERE id=$1',[id,v.scanStatus==='clean'?'clean':v.scanStatus==='error'?'corrupt':'rejected']);await c.query('INSERT INTO qayyum.rights_reviews(file_id,rights_status,license_name,license_url,license_text,rights_holder,access_status,decision,reviewer_id,reviewed_at,expires_at,notes) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9,now(),$10,$11)',[id,v.rightsStatus,v.licenseName||null,v.licenseUrl||null,v.licenseText||null,v.rightsHolder||null,v.accessStatus,v.decision,req.user.sub,v.expiresAt||null,v.notes||null]);await c.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'file_rights_review','digital_file',$2,$3)",[req.user.sub,id,JSON.stringify({scanStatus:v.scanStatus,rightsStatus:v.rightsStatus,decision:v.decision})]);await c.query('COMMIT');res.json({fileId:id,scanStatus:v.scanStatus,decision:v.decision})}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.post('/api/admin/works/:id/publish',auth,admin,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({decision:z.enum(['approved','rejected']),note:z.string().min(5).max(5000)}).parse(req.body);const q=await pool.query("UPDATE qayyum.works SET publication_status=$2,updated_at=now() WHERE id=$1 AND publication_status IN ('draft','in_review') RETURNING id,publication_status",[id,v.decision]);if(!q.rowCount)return res.status(404).json({error:'work_not_reviewable'});await pool.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'scientific_publication_review','work',$2,$3)",[req.user.sub,id,JSON.stringify({decision:v.decision,note:v.note})]);res.json(q.rows[0])}));
app.get('/api/admin/files/review-queue',auth,admin,safe(async(_q,res)=>{ready();const q=await pool.query("SELECT f.id AS file_id,f.original_filename,f.mime_type,f.file_size_bytes,f.checksum_sha256,f.created_at AS uploaded_at,p.scan_status,p.uploaded_by,r.id AS rights_review_id,r.rights_status,r.access_status,r.decision,r.notes AS review_notes,r.reviewed_at,r.expires_at FROM qayyum.digital_files f JOIN qayyum.private_file_objects p ON p.digital_file_id=f.id LEFT JOIN LATERAL (SELECT rr.* FROM qayyum.rights_reviews rr WHERE rr.file_id=f.id ORDER BY rr.reviewed_at DESC NULLS LAST,rr.id DESC LIMIT 1) r ON true WHERE p.scan_status IN ('pending','error') OR r.decision='hold' OR r.id IS NULL ORDER BY f.created_at ASC LIMIT 200");res.json({items:q.rows})}));
app.get('/api/admin/review/rights',auth,admin,safe(async(_q,res)=>{ready();const q=await pool.query("SELECT r.*,f.original_filename,p.scan_status FROM qayyum.rights_reviews r JOIN qayyum.digital_files f ON f.id=r.file_id JOIN qayyum.private_file_objects p ON p.digital_file_id=f.id WHERE r.id=(SELECT rr.id FROM qayyum.rights_reviews rr WHERE rr.file_id=f.id ORDER BY rr.reviewed_at DESC NULLS LAST,rr.id DESC LIMIT 1) AND r.decision='hold' ORDER BY f.created_at ASC LIMIT 200");res.json({items:q.rows})}));

// User support tickets: private to the requester and authorized staff.
app.post('/api/support/tickets',auth,safe(async(req,res)=>{ready();const v=z.object({category:z.string().min(2).max(32),subject:z.string().trim().min(3).max(300),body:z.string().trim().min(5).max(12000),priority:z.enum(['normal','important','urgent']).default('normal')}).parse(req.body);const c=await pool.connect();try{await c.query('BEGIN');const t=await c.query('INSERT INTO qayyum.support_tickets(user_id,category,priority,subject) VALUES($1,$2,$3,$4) RETURNING id,ticket_no,status,created_at',[req.user.sub,v.category,v.priority,v.subject]);await c.query('INSERT INTO qayyum.support_ticket_messages(ticket_id,sender_user_id,body) VALUES($1,$2,$3)',[t.rows[0].id,req.user.sub,v.body]);await c.query('COMMIT');res.status(201).json(t.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.get('/api/support/tickets',auth,safe(async(req,res)=>{ready();const q=await pool.query(`SELECT t.id,t.ticket_no,t.category,t.priority,t.status,t.subject,t.created_at,t.updated_at,(SELECT body FROM qayyum.support_ticket_messages m WHERE m.ticket_id=t.id ORDER BY m.created_at DESC LIMIT 1) AS last_message FROM qayyum.support_tickets t WHERE t.user_id=$1 ORDER BY t.updated_at DESC LIMIT 100`,[req.user.sub]);res.json({items:q.rows})}));
app.get('/api/support/tickets/:id/messages',auth,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const q=await pool.query(`SELECT m.id,m.body,m.created_at,m.sender_user_id,COALESCE(p.display_name,'عضو') AS sender FROM qayyum.support_ticket_messages m JOIN qayyum.support_tickets t ON t.id=m.ticket_id LEFT JOIN qayyum.user_profiles p ON p.user_id=m.sender_user_id WHERE t.id=$1 AND (t.user_id=$2 OR ($3::boolean AND (t.assigned_to=$2 OR $3))) ORDER BY m.created_at LIMIT 300`,[id,req.user.sub,['owner','admin'].includes(req.user.account_type)]);if(!q.rowCount)return res.status(404).json({error:'ticket_not_found'});res.json({items:q.rows})}));
app.post('/api/support/tickets/:id/messages',auth,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({body:z.string().trim().min(1).max(12000)}).parse(req.body);const t=await pool.query("SELECT id FROM qayyum.support_tickets WHERE id=$1 AND user_id=$2 AND status NOT IN ('closed')",[id,req.user.sub]);if(!t.rowCount)return res.status(404).json({error:'open_ticket_not_found'});const c=await pool.connect();try{await c.query('BEGIN');const m=await c.query('INSERT INTO qayyum.support_ticket_messages(ticket_id,sender_user_id,body) VALUES($1,$2,$3) RETURNING id,created_at',[id,req.user.sub,v.body]);await c.query("UPDATE qayyum.support_tickets SET status=CASE WHEN status='waiting_user' THEN 'in_progress' ELSE status END,updated_at=now() WHERE id=$1",[id]);await c.query('COMMIT');res.status(201).json(m.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.get('/api/admin/support/tickets',auth,admin,safe(async(req,res)=>{ready();const owner=req.user.account_type==='owner';const q=await pool.query(`SELECT t.id,t.ticket_no,t.user_id,t.assigned_to,t.category,t.priority,t.status,t.subject,t.created_at,t.updated_at,COALESCE(p.display_name,'مستخدم') AS requester FROM qayyum.support_tickets t LEFT JOIN qayyum.user_profiles p ON p.user_id=t.user_id WHERE ($1::boolean OR t.assigned_to=$2 OR t.assigned_to IS NULL) ORDER BY CASE t.priority WHEN 'urgent' THEN 0 WHEN 'important' THEN 1 ELSE 2 END,t.created_at LIMIT 200`,[owner,req.user.sub]);res.json({items:q.rows})}));
app.patch('/api/admin/support/tickets/:id',auth,admin,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({status:z.enum(['reviewing','assigned','in_progress','waiting_user','resolved','closed','appealed']),assignToSelf:z.boolean().default(false),note:z.string().max(2000).optional()}).parse(req.body);const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query(`UPDATE qayyum.support_tickets SET status=$2,assigned_to=CASE WHEN $3 THEN $4 ELSE assigned_to END,updated_at=now() WHERE id=$1 AND ($5::boolean OR assigned_to=$4 OR assigned_to IS NULL) RETURNING id,ticket_no,status,assigned_to`,[id,v.status,v.assignToSelf,req.user.sub,req.user.account_type==='owner']);if(!q.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'ticket_not_found_or_not_assigned'})}await c.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'support_ticket_updated','support_ticket',$2,$3)",[req.user.sub,id,JSON.stringify({status:v.status,assignToSelf:v.assignToSelf,note:v.note||null})]);await c.query('COMMIT');res.json(q.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.post('/api/admin/support/tickets/:id/messages',auth,admin,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({body:z.string().trim().min(1).max(12000)}).parse(req.body);const t=await pool.query('SELECT id FROM qayyum.support_tickets WHERE id=$1 AND ($2::boolean OR assigned_to=$3 OR assigned_to IS NULL)',[id,req.user.account_type==='owner',req.user.sub]);if(!t.rowCount)return res.status(404).json({error:'ticket_not_found_or_not_assigned'});const c=await pool.connect();try{await c.query('BEGIN');const m=await c.query('INSERT INTO qayyum.support_ticket_messages(ticket_id,sender_user_id,body) VALUES($1,$2,$3) RETURNING id,created_at',[id,req.user.sub,v.body]);await c.query("UPDATE qayyum.support_tickets SET status='waiting_user',updated_at=now() WHERE id=$1",[id]);await c.query('COMMIT');res.status(201).json(m.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));

// Moderation reports and appeals. Reporters see only their own submissions; moderation is staff-only.
app.post('/api/moderation/reports',auth,safe(async(req,res)=>{ready();const v=z.object({targetKind:z.enum(['user','post','group','channel','book','research','other']),targetId:z.string().trim().min(1).max(200),violationKind:z.string().min(2).max(64),severity:z.enum(['low','normal','high','critical']).default('normal'),description:z.string().trim().min(5).max(12000),evidence:z.array(z.object({label:z.string().max(200),url:z.string().url().max(2000).optional()})).max(10).default([])}).parse(req.body);const q=await pool.query("INSERT INTO qayyum.moderation_reports(reporter_user_id,target_kind,target_id,violation_kind,severity,description,evidence) VALUES($1,$2,$3,$4,$5,$6,$7::jsonb) RETURNING id,status,created_at",[req.user.sub,v.targetKind,v.targetId,v.violationKind,v.severity,v.description,JSON.stringify(v.evidence)]);res.status(201).json(q.rows[0])}));
app.get('/api/moderation/reports/mine',auth,safe(async(req,res)=>{ready();const q=await pool.query('SELECT id,target_kind,target_id,violation_kind,severity,status,created_at FROM qayyum.moderation_reports WHERE reporter_user_id=$1 ORDER BY created_at DESC LIMIT 100',[req.user.sub]);res.json({items:q.rows})}));
app.get('/api/admin/moderation/reports',auth,admin,safe(async(req,res)=>{ready();const v=z.object({status:z.enum(['received','reviewing','assigned','decided','dismissed','appealed','closed']).optional()}).parse(req.query);const owner=req.user.account_type==='owner';const q=await pool.query(`SELECT r.id,r.reporter_user_id,r.target_kind,r.target_id,r.violation_kind,r.severity,r.description,r.evidence,r.status,r.assigned_to,r.created_at,COALESCE(p.display_name,'حساب محذوف') AS reporter FROM qayyum.moderation_reports r LEFT JOIN qayyum.user_profiles p ON p.user_id=r.reporter_user_id WHERE ($1::text IS NULL OR r.status=$1) AND ($2::boolean OR r.assigned_to=$3 OR r.assigned_to IS NULL) ORDER BY CASE r.severity WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'normal' THEN 2 ELSE 3 END,r.created_at LIMIT 200`,[v.status||null,owner,req.user.sub]);res.json({items:q.rows})}));
app.patch('/api/admin/moderation/reports/:id/assign',auth,admin,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({assignToSelf:z.boolean().default(true)}).parse(req.body);const q=await pool.query("UPDATE qayyum.moderation_reports SET assigned_to=$2,status='assigned' WHERE id=$1 AND ($3::boolean OR assigned_to IS NULL OR assigned_to=$2) RETURNING id,status,assigned_to",[id,v.assignToSelf?req.user.sub:null,req.user.account_type==='owner']);if(!q.rowCount)return res.status(404).json({error:'report_not_found_or_already_assigned'});res.json(q.rows[0])}));
app.post('/api/admin/moderation/reports/:id/decision',auth,admin,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({decision:z.enum(['warning','notice','restrict','temporary_ban','permanent_ban','dismiss']),reason:z.string().trim().min(5).max(5000),expiresAt:z.string().datetime({offset:true}).optional()}).parse(req.body);const c=await pool.connect();try{await c.query('BEGIN');const r=await c.query('SELECT id,target_kind,target_id,assigned_to FROM qayyum.moderation_reports WHERE id=$1 FOR UPDATE',[id]);if(!r.rowCount||!(req.user.account_type==='owner'||!r.rows[0].assigned_to||r.rows[0].assigned_to===req.user.sub)){await c.query('ROLLBACK');return res.status(404).json({error:'report_not_found_or_not_assigned'})}const d=await c.query('INSERT INTO qayyum.moderation_decisions(report_id,decision_kind,reason,issued_by,expires_at) VALUES($1,$2,$3,$4,$5) RETURNING id,decision_kind,created_at',[id,v.decision,v.reason,req.user.sub,v.expiresAt||null]);await c.query("UPDATE qayyum.moderation_reports SET status=$2,assigned_to=COALESCE(assigned_to,$3) WHERE id=$1",[id,v.decision==='dismiss'?'dismissed':'decided',req.user.sub]);await c.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'moderation_decision_issued','moderation_report',$2,$3)",[req.user.sub,id,JSON.stringify({decision:v.decision,reason:v.reason})]);await c.query('COMMIT');res.status(201).json(d.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.get('/api/moderation/decisions/mine',auth,safe(async(req,res)=>{ready();const q=await pool.query(`SELECT d.id,d.decision_kind,d.reason,d.expires_at,d.created_at,r.target_kind,r.target_id,r.id AS report_id FROM qayyum.moderation_decisions d JOIN qayyum.moderation_reports r ON r.id=d.report_id WHERE r.target_kind='user' AND r.target_id=$1 ORDER BY d.created_at DESC LIMIT 50`,[req.user.sub]);res.json({items:q.rows})}));
app.post('/api/moderation/decisions/:id/appeals',auth,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({text:z.string().trim().min(20).max(10000)}).parse(req.body);const c=await pool.connect();try{await c.query('BEGIN');const d=await c.query(`SELECT d.id,r.id AS report_id FROM qayyum.moderation_decisions d JOIN qayyum.moderation_reports r ON r.id=d.report_id WHERE d.id=$1 AND r.target_kind='user' AND r.target_id=$2 FOR UPDATE`,[id,req.user.sub]);if(!d.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'appealable_decision_not_found'})}const existing=await c.query("SELECT id FROM qayyum.moderation_appeals WHERE decision_id=$1 AND appellant_user_id=$2 AND status='pending'",[id,req.user.sub]);if(existing.rowCount){await c.query('ROLLBACK');return res.status(409).json({error:'appeal_already_pending'})}const a=await c.query("INSERT INTO qayyum.moderation_appeals(decision_id,appellant_user_id,appeal_text) VALUES($1,$2,$3) RETURNING id,status,created_at",[id,req.user.sub,v.text]);await c.query("UPDATE qayyum.moderation_reports SET status='appealed' WHERE id=$1",[d.rows[0].report_id]);await c.query('COMMIT');res.status(201).json(a.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.get('/api/admin/moderation/appeals',auth,admin,safe(async(req,res)=>{ready();const q=await pool.query(`SELECT a.id,a.decision_id,a.appellant_user_id,a.appeal_text,a.status,a.created_at,d.decision_kind,d.reason,COALESCE(p.display_name,'عضو') AS appellant FROM qayyum.moderation_appeals a JOIN qayyum.moderation_decisions d ON d.id=a.decision_id LEFT JOIN qayyum.user_profiles p ON p.user_id=a.appellant_user_id WHERE a.status='pending' ORDER BY a.created_at LIMIT 200`);res.json({items:q.rows})}));
app.patch('/api/admin/moderation/appeals/:id',auth,admin,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({status:z.enum(['accepted','rejected','returned']),note:z.string().trim().min(5).max(5000)}).parse(req.body);const q=await pool.query("UPDATE qayyum.moderation_appeals SET status=$2,reviewed_by=$3,decision_note=$4,decided_at=now() WHERE id=$1 AND status='pending' RETURNING id,status,decided_at",[id,v.status,req.user.sub,v.note]);if(!q.rowCount)return res.status(404).json({error:'pending_appeal_not_found'});await pool.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'moderation_appeal_reviewed','moderation_appeal',$2,$3)",[req.user.sub,id,JSON.stringify({status:v.status,note:v.note})]);res.json(q.rows[0])}));

// Community spaces: groups and channels. New spaces and posts remain pending until reviewed.
app.get('/api/community/spaces',auth,safe(async(req,res)=>{ready();const v=z.object({kind:z.enum(['group','channel']).optional(),q:z.string().max(120).optional()}).parse(req.query);const q=await pool.query(`SELECT s.id,s.space_kind,s.name,s.slug,s.description,s.privacy,s.status,s.created_at,COALESCE(m.member_role,'') AS my_role,COALESCE(m.membership_status,'') AS my_membership,(SELECT count(*)::int FROM qayyum.community_members cm WHERE cm.space_id=s.id AND cm.membership_status='active') AS member_count FROM qayyum.community_spaces s LEFT JOIN qayyum.community_members m ON m.space_id=s.id AND m.user_id=$1 WHERE s.status='active' AND (s.privacy='public' OR m.membership_status='active' OR m.membership_status='pending') AND ($2::text IS NULL OR s.space_kind=$2) AND ($3::text IS NULL OR s.name ILIKE '%'||$3||'%' OR COALESCE(s.description,'') ILIKE '%'||$3||'%') ORDER BY s.created_at DESC LIMIT 100`,[req.user.sub,v.kind||null,v.q||null]);res.json({items:q.rows})}));
app.post('/api/community/spaces',auth,safe(async(req,res)=>{ready();const v=z.object({kind:z.enum(['group','channel']),name:z.string().trim().min(3).max(240),description:z.string().trim().max(4000).optional(),privacy:z.enum(['public','private']).default('public')}).parse(req.body);const slug=`${v.name.toLowerCase().normalize('NFKD').replace(/[^a-z0-9\u0600-\u06ff]+/g,'-').replace(/^-|-$/g,'').slice(0,220)}-${crypto.randomBytes(3).toString('hex')}`;const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query(`INSERT INTO qayyum.community_spaces(created_by,space_kind,name,slug,description,privacy,status) VALUES($1,$2,$3,$4,$5,$6,'pending_owner_review') RETURNING id,space_kind,name,slug,privacy,status,created_at`,[req.user.sub,v.kind,v.name,slug,v.description||null,v.privacy]);await c.query(`INSERT INTO qayyum.community_members(space_id,user_id,member_role,membership_status) VALUES($1,$2,'manager','active')`,[q.rows[0].id,req.user.sub]);await c.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'community_space_submitted','community_space',$2,$3)",[req.user.sub,q.rows[0].id,JSON.stringify({kind:v.kind,name:v.name})]);await c.query('COMMIT');res.status(201).json(q.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.post('/api/community/spaces/:id/join',auth,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const q=await pool.query("SELECT id,privacy,status FROM qayyum.community_spaces WHERE id=$1 AND status='active'",[id]);if(!q.rowCount)return res.status(404).json({error:'space_not_found'});const state=q.rows[0].privacy==='public'?'active':'pending';const m=await pool.query(`INSERT INTO qayyum.community_members(space_id,user_id,member_role,membership_status) VALUES($1,$2,'member',$3) ON CONFLICT(space_id,user_id) DO UPDATE SET membership_status=CASE WHEN qayyum.community_members.membership_status IN ('banned','muted') THEN qayyum.community_members.membership_status ELSE EXCLUDED.membership_status END RETURNING membership_status`,[id,req.user.sub,state]);if(['banned','muted'].includes(m.rows[0].membership_status))return res.status(403).json({error:'membership_restricted'});res.status(201).json({spaceId:id,status:m.rows[0].membership_status})}));
app.delete('/api/community/spaces/:id/membership',auth,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const q=await pool.query("UPDATE qayyum.community_members SET membership_status='left' WHERE space_id=$1 AND user_id=$2 AND membership_status IN ('active','pending') RETURNING space_id",[id,req.user.sub]);if(!q.rowCount)return res.status(404).json({error:'membership_not_found'});res.status(204).end()}));
app.get('/api/community/spaces/:id/posts',auth,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const access=await pool.query(`SELECT s.id,s.space_kind,s.privacy,m.membership_status,m.member_role FROM qayyum.community_spaces s LEFT JOIN qayyum.community_members m ON m.space_id=s.id AND m.user_id=$2 WHERE s.id=$1 AND s.status='active' AND (s.privacy='public' OR m.membership_status='active')`,[id,req.user.sub]);if(!access.rowCount)return res.status(404).json({error:'space_not_found'});const q=await pool.query(`SELECT p.id,p.body,p.parent_post_id,p.created_at,p.author_user_id,COALESCE(u.display_name,'عضو') AS author FROM qayyum.community_posts p LEFT JOIN qayyum.user_profiles u ON u.user_id=p.author_user_id WHERE p.space_id=$1 AND p.moderation_status='visible' ORDER BY p.created_at DESC LIMIT 100`,[id]);res.json({space:access.rows[0],items:q.rows})}));
app.post('/api/community/spaces/:id/posts',auth,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({body:z.string().trim().min(2).max(12000),parentPostId:z.string().uuid().optional()}).parse(req.body);const m=await pool.query(`SELECT s.space_kind,m.member_role,m.membership_status FROM qayyum.community_spaces s JOIN qayyum.community_members m ON m.space_id=s.id AND m.user_id=$2 WHERE s.id=$1 AND s.status='active'`,[id,req.user.sub]);if(!m.rowCount||m.rows[0].membership_status!=='active')return res.status(403).json({error:'active_membership_required'});if(m.rows[0].space_kind==='channel'&&!['manager','moderator'].includes(m.rows[0].member_role))return res.status(403).json({error:'channel_publish_permission_required'});if(v.parentPostId){const parent=await pool.query("SELECT id FROM qayyum.community_posts WHERE id=$1 AND space_id=$2 AND moderation_status='visible'",[v.parentPostId,id]);if(!parent.rowCount)return res.status(404).json({error:'parent_post_not_found'})}const q=await pool.query(`INSERT INTO qayyum.community_posts(space_id,author_user_id,parent_post_id,body,moderation_status) VALUES($1,$2,$3,$4,'pending') RETURNING id,moderation_status,created_at`,[id,req.user.sub,v.parentPostId||null,v.body]);res.status(201).json(q.rows[0])}));
app.get('/api/admin/community/spaces',auth,ownerOnly,safe(async(req,res)=>{ready();const status=z.enum(['pending_owner_review','active','paused','rejected','archived']).optional().parse(req.query.status);const q=await pool.query(`SELECT s.id,s.space_kind,s.name,s.description,s.privacy,s.status,s.created_at,COALESCE(p.display_name,'عضو') AS creator FROM qayyum.community_spaces s LEFT JOIN qayyum.user_profiles p ON p.user_id=s.created_by WHERE ($1::text IS NULL OR s.status=$1) ORDER BY CASE s.status WHEN 'pending_owner_review' THEN 0 WHEN 'active' THEN 1 ELSE 2 END,s.created_at DESC LIMIT 300`,[status||null]);res.json({items:q.rows})}));
app.patch('/api/admin/community/spaces/:id',auth,ownerOnly,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({status:z.enum(['active','rejected','paused','archived']),note:z.string().trim().min(3).max(2000)}).parse(req.body);const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query("UPDATE qayyum.community_spaces SET status=$2 WHERE id=$1 RETURNING id,space_kind,name,status",[id,v.status]);if(!q.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'community_space_not_found'})}await c.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'community_space_reviewed','community_space',$2,$3)",[req.user.sub,id,JSON.stringify({status:v.status,note:v.note})]);await c.query('COMMIT');res.json(q.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.get('/api/admin/community/spaces/:id/members',auth,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const own=req.user.account_type==='owner';const q=await pool.query(`SELECT s.id FROM qayyum.community_spaces s WHERE s.id=$1 AND ($2::boolean OR EXISTS(SELECT 1 FROM qayyum.community_members m WHERE m.space_id=s.id AND m.user_id=$3 AND m.member_role IN ('manager','moderator') AND m.membership_status='active'))`,[id,own,req.user.sub]);if(!q.rowCount)return res.status(404).json({error:'space_not_found_or_not_managed'});const m=await pool.query(`SELECT cm.user_id,cm.member_role,cm.membership_status,cm.joined_at,COALESCE(p.display_name,'عضو') AS display_name FROM qayyum.community_members cm LEFT JOIN qayyum.user_profiles p ON p.user_id=cm.user_id WHERE cm.space_id=$1 ORDER BY cm.joined_at`,[id]);res.json({items:m.rows})}));
app.patch('/api/admin/community/spaces/:id/members/:userId',auth,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id),userId=z.string().uuid().parse(req.params.userId);const v=z.object({role:z.enum(['member','moderator','manager']).optional(),status:z.enum(['active','muted','banned','left']).optional()}).refine(x=>x.role||x.status).parse(req.body);const owner=req.user.account_type==='owner';const manager=await pool.query(`SELECT 1 FROM qayyum.community_spaces s WHERE s.id=$1 AND ($2::boolean OR EXISTS(SELECT 1 FROM qayyum.community_members m WHERE m.space_id=s.id AND m.user_id=$3 AND m.member_role IN ('manager','moderator') AND m.membership_status='active'))`,[id,owner,req.user.sub]);if(!manager.rowCount)return res.status(404).json({error:'space_not_found_or_not_managed'});if(v.role&&v.role!=='member'&&!owner)return res.status(403).json({error:'owner_required_to_grant_moderator_role'});const q=await pool.query(`UPDATE qayyum.community_members SET member_role=COALESCE($3,member_role),membership_status=COALESCE($4,membership_status) WHERE space_id=$1 AND user_id=$2 RETURNING space_id,user_id,member_role,membership_status`,[id,userId,v.role||null,v.status||null]);if(!q.rowCount)return res.status(404).json({error:'community_member_not_found'});await pool.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'community_member_updated','community_space',$2,$3)",[req.user.sub,id,JSON.stringify({userId,...v})]);res.json(q.rows[0])}));
app.get('/api/admin/community/spaces/:id/posts/pending',auth,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const own=req.user.account_type==='owner';const access=await pool.query(`SELECT 1 FROM qayyum.community_spaces s WHERE s.id=$1 AND ($2::boolean OR EXISTS(SELECT 1 FROM qayyum.community_members m WHERE m.space_id=s.id AND m.user_id=$3 AND m.member_role IN ('manager','moderator') AND m.membership_status='active'))`,[id,own,req.user.sub]);if(!access.rowCount)return res.status(404).json({error:'space_not_found_or_not_moderated'});const q=await pool.query(`SELECT p.id,p.body,p.author_user_id,p.created_at,COALESCE(u.display_name,'عضو') AS author FROM qayyum.community_posts p LEFT JOIN qayyum.user_profiles u ON u.user_id=p.author_user_id WHERE p.space_id=$1 AND p.moderation_status='pending' ORDER BY p.created_at`,[id]);res.json({items:q.rows})}));
app.patch('/api/admin/community/posts/:id/moderation',auth,safe(async(req,res)=>{ready();const id=z.string().uuid().parse(req.params.id);const v=z.object({status:z.enum(['visible','held','removed']),note:z.string().trim().min(3).max(2000)}).parse(req.body);const own=req.user.account_type==='owner';const q=await pool.query(`UPDATE qayyum.community_posts p SET moderation_status=$2 WHERE p.id=$1 AND p.moderation_status='pending' AND ($3::boolean OR EXISTS(SELECT 1 FROM qayyum.community_members m WHERE m.space_id=p.space_id AND m.user_id=$4 AND m.member_role IN ('manager','moderator') AND m.membership_status='active')) RETURNING p.id,p.space_id,p.moderation_status`,[id,v.status,own,req.user.sub]);if(!q.rowCount)return res.status(404).json({error:'pending_post_not_found_or_not_moderated'});await pool.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'community_post_moderated','community_post',$2,$3)",[req.user.sub,id,JSON.stringify({status:v.status,note:v.note})]);res.json(q.rows[0])}));


app.get('/api/admin/dashboard/stats',auth,ownerOnly,safe(async(_req,res)=>{ready();const q=await pool.query(`
SELECT
 (SELECT COUNT(*)::int FROM qayyum.works) AS books,
 (SELECT COUNT(*)::int FROM qayyum.users WHERE account_type<>'owner') AS members,
 (SELECT COUNT(*)::int FROM qayyum.community_spaces) AS spaces,
 ((SELECT COUNT(*) FROM qayyum.owner_approval_queue WHERE status='pending')+
  (SELECT COUNT(*) FROM qayyum.review_tasks WHERE status='pending'))::int AS pending_reviews
`);res.json(q.rows[0]||{books:0,members:0,spaces:0,pending_reviews:0})}));

app.get('/api/admin/backups',auth,ownerOnly,safe(async(_req,res)=>{ready();const [policies,runs]=await Promise.all([pool.query('SELECT id,policy_name,cadence,enabled,retention_count,encryption_required,created_at FROM qayyum.backup_policies ORDER BY id'),pool.query('SELECT id,policy_id,started_at,completed_at,status,checksum_sha256,encrypted,byte_size,result_note FROM qayyum.backup_runs ORDER BY started_at DESC LIMIT 100')]);res.json({policies:policies.rows,runs:runs.rows,executionConfigured:false})}));
app.patch('/api/admin/backups/policies/:id',auth,ownerOnly,safe(async(req,res)=>{ready();const id=z.coerce.number().int().positive().parse(req.params.id);const v=z.object({enabled:z.boolean().optional(),cadence:z.enum(['daily','weekly','monthly','manual']).optional(),retentionCount:z.number().int().min(1).max(365).optional()}).refine(x=>Object.keys(x).length>0).parse(req.body);const q=await pool.query('UPDATE qayyum.backup_policies SET enabled=COALESCE($2,enabled),cadence=COALESCE($3,cadence),retention_count=COALESCE($4,retention_count) WHERE id=$1 RETURNING id,policy_name,cadence,enabled,retention_count,encryption_required',[id,v.enabled??null,v.cadence??null,v.retentionCount??null]);if(!q.rowCount)return res.status(404).json({error:'backup_policy_not_found'});await pool.query("INSERT INTO qayyum.audit_logs(actor_user_id,action_code,target_kind,target_id,details) VALUES($1,'backup_policy_updated','backup_policy',$2,$3)",[req.user.sub,String(id),JSON.stringify(v)]);res.json(q.rows[0])}));
app.get('/api/admin/audit-logs',auth,ownerOnly,safe(async(req,res)=>{ready();const limit=Math.min(Math.max(Number(req.query.limit)||100,1),200);const q=await pool.query(`SELECT a.id,a.action_code,a.target_kind,a.target_id,a.details,a.created_at,COALESCE(p.display_name,'حساب إداري') AS actor_name FROM qayyum.audit_logs a LEFT JOIN qayyum.user_profiles p ON p.user_id=a.actor_user_id ORDER BY a.created_at DESC LIMIT $1`,[limit]);res.json({items:q.rows})}));
app.use((err,req,res,_next)=>{if(err instanceof z.ZodError)return res.status(400).json({error:'validation_error',details:err.issues});const status=err.status|| (err instanceof multer.MulterError?400:500);if(status>=500)console.error('[API_ERROR]',JSON.stringify({method:req.method,path:req.path,name:err.name||'Error',code:err.code||null,message:err.message||'Unknown error'}));res.status(status).json({error:status===500?'internal_error':err.message})});
const port=Number(process.env.PORT||8787); if(process.env.NODE_ENV!=='test')app.listen(port,()=>console.log(`Qayyum API listening on ${port}`));
export {app,pool};
